function applyTheme(next){theme={...DEFAULT_THEME,...next};Object.entries(theme).forEach(([k,v])=>document.documentElement.style.setProperty('--'+k,v));document.querySelectorAll('[data-theme-key]').forEach(i=>{if(theme[i.dataset.themeKey])i.value=theme[i.dataset.themeKey]});const active=Object.entries(THEME_PRESETS).find(([id,p])=>Object.keys(DEFAULT_THEME).every(k=>theme[k]===p[k]));document.querySelectorAll('[data-theme-preset]').forEach(b=>b.classList.toggle('active',!!active&&b.dataset.themePreset===active[0]));}
