function teamLogoForName(name,small=false){const n=String(name||'').trim();const ab=teamNameToAb[n];return logoMarkup(ab||n,n,small)}
function betTeamName(v,fallback){return String(v||fallback||'').trim()}
function currentFranchiseLabel(){return String(currentData?.fileName||'').trim()||'No Franchise loaded'}
function currentFranchiseKey(){if(!currentData)return '';const teams=(currentData.teams||[]).map(t=>teamName(t)).filter(Boolean).sort().join('|');return String(hashString(`${currentData.fileName||''}|${currentData.gameYear||''}|${teams}`))}
function legacyFranchiseKey(){if(!currentData)return '';const sig=(currentData.games||[]).map(g=>[g.SeasonWeek,g.SeasonGameNum,g.AwayTeam,g.HomeTeam].join(':')).join('|');return String(hashString(`${currentData.fileName||''}|${currentData.gameYear||''}|${sig}`))}
function betBelongsToCurrentFranchise(b){if(!currentData||!b)return false;const key=currentFranchiseKey();if(b.franchiseKey===key)return true;return String(b.franchiseName||'')===currentFranchiseLabel()&&String(b.franchiseYear??'')===String(currentData.gameYear??'')}
function betSaveLabel(b){return String(b?.franchiseName||'').trim()||'Save not recorded'}
function betSaveClass(b){return b?.franchiseName?'history-save':'history-save missing'}

function logoMarkup(ab,name,small=false){const key=String(ab||'').toUpperCase();const n=String(name||'').trim();const url=teamLogoUrls[key]||relocationLogoUrls[n];const fallback=String(ab||name||'?').slice(0,3).toUpperCase();if(!url)return `<div class="logo-fallback${small?' logo-sm':''}">${fallback}</div>`;const cls=relocationLogoUrls[n]&&!teamLogoUrls[key]?'team-logo-img relocation-logo':'team-logo-img';return `<img class="${cls}${small?' logo-sm':''}" src="${url}" alt="${n||key}" title="${n||key}" onerror="this.style.display='none';this.nextElementSibling.style.display='grid'"> <div class="logo-fallback${small?' logo-sm':''}" style="display:none">${fallback}</div>`}
function teamLogoCell(ab,name){return `<div class="logo">${logoMarkup(ab,name)}</div>`}
function gameKey(g){return [g.phase||'regular',g.phaseWeek??g.SeasonWeek,g.SeasonGameNum,g.AwayTeam,g.HomeTeam].join('|')}
function isPlayed(g){return g?.isPlayed===true}
function gameTimeMinutes(g){const n=g?.gameTimeMinutes;return n===null||n===undefined||n===''||!Number.isFinite(Number(n))?null:Number(n)}function formatGameTime(g){const mins=gameTimeMinutes(g);if(mins===null)return 'TIME TBD';const h=Math.floor(mins/60)%24,m=mins%60;const ap=h>=12?'PM':'AM';const hh=(h%12)||12;return `${hh}:${String(m).padStart(2,'0')} ${ap}`}function daySort(g){const order={Thursday:0,Friday:1,Saturday:2,Sunday:3,Monday:4,Tuesday:5,Wednesday:6};return order[String(g.DayOfWeek||'')]??9}function gameSort(a,b){const dayDelta=daySort(a)-daySort(b);if(dayDelta)return dayDelta;const at=gameTimeMinutes(a),bt=gameTimeMinutes(b);if(at!==null&&bt!==null&&at!==bt)return at-bt;if(at!==null&&bt===null)return -1;if(at===null&&bt!==null)return 1;return Number(a.SeasonGameNum)-Number(b.SeasonGameNum)}function currentGameSet(){if(!currentData)return[]; const phase=window.selectedPhase||'regular'; const w=Number(document.getElementById('week').value); return games.filter(g=>String(g.phase||'regular')===phase&&Number(g.phaseWeek)===w).sort(gameSort)}
function statsForTeam(id){const rows=games.filter(g=>isPlayed(g)&&String(g.phase||'regular')==='regular'&&(g.AwayTeam===id||g.HomeTeam===id));let w=0,l=0,t=0,pf=0,pa=0;for(const g of rows){const a=Number(g.AwayScore)||0,h=Number(g.HomeScore)||0;if(g.AwayTeam===id){pf+=a;pa+=h;if(a>h)w++;else if(a<h)l++;else t++;}else{pf+=h;pa+=a;if(h>a)w++;else if(h<a)l++;else t++;}}return{w,l,t,pf,pa,gp:rows.length}}
function hashString(str){let h=2166136261;for(let i=0;i<String(str).length;i++){h^=String(str).charCodeAt(i);h=Math.imul(h,16777619)}return h>>>0}
function priceFromProbability(p){const q=Math.min(.67,Math.max(.33,Number(p)||.5));return q>=.5?-Math.round(100*q/(1-q)):Math.round(100*(1-q)/q)}
function juicePair(g,kind,spread){const magnitude=Math.abs(Number(spread)||0);let fav=-110,dog=-110;if(kind==='spread'){if(magnitude>=7)fav=-115,dog=-105;else if(magnitude>=3.5)fav=-112,dog=-108;else if(magnitude>=1.5)fav=-110,dog=-110;const n=hashString(gameKey(g))%3;if(n===0&&fav===-110){fav=-108;dog=-112}else if(n===2&&fav===-110){fav=-112;dog=-108}}else{const n=hashString(gameKey(g)+'|'+kind)%5;if(n===0){fav=-115;dog=-105}else if(n===1){fav=-112;dog=-108}else if(n===2){fav=-108;dog=-112}}return{fav,dog}}
function modelLine(g){const a=statsForTeam(g.AwayTeam),h=statsForTeam(g.HomeTeam);const ar=a.gp?((a.pf-a.pa)/a.gp):0,hr=h.gp?((h.pf-h.pa)/h.gp):0;const margin=(hr-ar)+2.5;const total=a.gp&&h.gp?((a.pf+a.pa)/a.gp+(h.pf+h.pa)/h.gp)/2:44.5;let homeProb=1/(1+Math.exp(-margin/6));homeProb=Math.min(.82,Math.max(.18,homeProb));const vig=.045;let hp=homeProb*(1-vig/2),ap=(1-homeProb)*(1-vig/2);const homeML=hp>=.5?-Math.round(100*hp/(1-hp)):Math.round(100*(1-hp)/hp);const awayML=ap>=.5?-Math.round(100*ap/(1-ap)):Math.round(100*(1-ap)/ap);const spread=Math.round(margin*2)/2;const lineTotal=Math.round(total*2)/2;const spreadJuice=juicePair(g,'spread',spread);const totalJuice=juicePair(g,'total',lineTotal);const awayFav=spread<0,homeFav=spread>0;const pickem=spread===0;const totalOverFav=(hashString(gameKey(g)+'|total-side')%2)===0;return{awayML:fmtOdds(awayML),homeML:fmtOdds(homeML),awaySpread:pickem?-110:(awayFav?spreadJuice.fav:spreadJuice.dog),homeSpread:pickem?-110:(homeFav?spreadJuice.fav:spreadJuice.dog),spread,over:totalOverFav?totalJuice.fav:totalJuice.dog,under:totalOverFav?totalJuice.dog:totalJuice.fav,total:lineTotal,aRec:`${a.w}-${a.l}${a.t?'-'+a.t:''}`,hRec:`${h.w}-${h.l}${h.t?'-'+h.t:''}`}}
function propOdds(m,side){const scales={passYds:15,passTD:.35,completions:1.5,rushYds:6,rushAtt:1.5,recYds:6,receptions:.9};const scale=scales[m.stat]||5;const edge=(Number(m.average)-Number(m.line))/scale*(side==='over'?1:-1);const fair=.5+Math.max(-.05,Math.min(.05,edge*.07));const vig=.045;return priceFromProbability(fair*(1+vig/2))}

function market(label,market,display,g,kind,lineArg){const raw=String(display);const m=raw.match(/([+-]\d+(?:\.\d+)?)$/);const odds=m?Number(m[1]):Number(display);const shown=m?raw.slice(0,m.index)+fmtOdds(odds):fmtOdds(odds);const line=lineArg!==undefined&&lineArg!==null?lineArg:(g.line||null);const savedDisplay=raw;return `<button class="market" data-add='${encodeURIComponent(JSON.stringify({label,market,display:savedDisplay,odds,gameId:gameKey(g),gameIndex:g.index,week:g.week,phase:g.phase||'regular',phaseWeek:g.phaseWeek,away:g.awayName,home:g.homeName,kind,line}))}'><span class="m">${market}</span><b>${shown}</b></button>`}
function gameResultLabel(g){const status=String(g.GameStatus||'').toLowerCase();if(status.includes('awaywon'))return `${g.awayName} WIN`;if(status.includes('homewon'))return `${g.homeName} WIN`;if(status.includes('tied'))return 'TIE';return 'FINAL'}
function statNum(stats,key){const n=Number(stats?.[key]);return Number.isFinite(n)?n:null}
function formatLeaderStats(stats){const parts=[];const passYds=statNum(stats,'passYds'),passTD=statNum(stats,'passTD'),ints=statNum(stats,'passInt'),comp=statNum(stats,'completions'),att=statNum(stats,'attempts');if(passYds!==null)parts.push(`PASS ${comp!==null&&att!==null?`${comp}/${att} `:''}${passYds} YDS${passTD!==null?` • ${passTD} TD`:''}${ints!==null?` • ${ints} INT`:''}`);const rushYds=statNum(stats,'rushYds'),rushAtt=statNum(stats,'rushAtt'),rushTD=statNum(stats,'rushTD');if(rushYds!==null)parts.push(`RUSH ${rushAtt!==null?`${rushAtt} ATT • `:''}${rushYds} YDS${rushTD!==null?` • ${rushTD} TD`:''}`);const recYds=statNum(stats,'recYds'),receptions=statNum(stats,'receptions'),recTD=statNum(stats,'recTD');if(recYds!==null)parts.push(`REC ${receptions!==null?`${receptions} REC • `:''}${recYds} YDS${recTD!==null?` • ${recTD} TD`:''}`);const tackles=statNum(stats,'tackles'),sacks=statNum(stats,'sacks'),defInt=statNum(stats,'defInt');if(tackles!==null||sacks!==null||defInt!==null)parts.push(`DEF${tackles!==null?` ${tackles} TKL`:''}${sacks!==null?` • ${sacks} SACK`:''}${defInt!==null?` • ${defInt} INT`:''}`);return parts}
function renderLeaderCard(players,teamName,gameIndex){
  const merged=new Map();
  for(const r of (currentData?.playerGameStats||[])){
    if(String(r.gameIndex)!==String(gameIndex))continue;
    const p=players.get(String(r.playerId));if(!p)continue;
    const teamId=String(teamName?.recordIndex??'');const playerTeamId=String(p.teamId??'');
    const playerTeamIndex=String(p.teamIndex??'');const teamIndex=String(teamName?.teamIndex??'');
    const targetName=String(teamName?.name||'').trim().toLowerCase();const playerName=String(p.teamName||'').trim().toLowerCase();
    const targetAb=String(teamName?.abbreviation||'').trim().toLowerCase();const playerAb=String(p.teamAbbreviation||'').trim().toLowerCase();
    const idMatch=teamId&&playerTeamId===teamId;const teamIndexMatch=teamIndex&&playerTeamIndex===teamIndex;
    const nameMatch=targetName&&playerName&&targetName===playerName;const abMatch=targetAb&&playerAb&&targetAb===playerAb;
    if(!idMatch&&!teamIndexMatch&&!nameMatch&&!abMatch)continue;
    const cur=merged.get(String(r.playerId))||{p,stats:{}};
    for(const [k,v] of Object.entries(r.stats||{})){const n=Number(v);if(Number.isFinite(n))cur.stats[k]=(cur.stats[k]||0)+n}
    merged.set(String(r.playerId),cur)
  }
  const rows=[...merged.values()];
  const pos=v=>String(v||'').toUpperCase().replace('INVALID_','');
  const hasPositive=(stats,keys)=>keys.some(k=>{const n=statNum(stats,k);return n!==null&&n>0});
  const sections=[
    {label:'PASSING',key:'passYds',headline:'PASS YDS',statKeys:['passYds','attempts','completions','passTD','passInt']},
    {label:'RUSHING',key:'rushYds',headline:'RUSH YDS',statKeys:['rushYds','rushAtt','rushTD']},
    {label:'RECEIVING',key:'recYds',headline:'REC YDS',statKeys:['recYds','receptions','recTD']}
  ];
  let html='';
  for(const section of sections){
    const ranked=rows.filter(x=>hasPositive(x.stats,section.statKeys)&&statNum(x.stats,section.key)!==null)
      .sort((a,b)=>statNum(b.stats,section.key)-statNum(a.stats,section.key)).slice(0,3);
    if(!ranked.length)continue;
    html+=`<div class="boxscore-category">${section.label}</div>`;
    html+=ranked.map(x=>{const primary=statNum(x.stats,section.key);const role=pos(x.p.position)||'';return `<div class="leader"><span>${x.p.name}${role?` <span class="boxscore-player-role">${role}</span>`:''}<div class="statline">${formatLeaderStats(x.stats).filter(v=>{if(section.label==='PASSING')return v.startsWith('PASS ');if(section.label==='RUSHING')return v.startsWith('RUSH ');if(section.label==='RECEIVING')return v.startsWith('REC ');return true}).map(v=>`<span class="statpill">${v}</span>`).join('')}</div></span><b>${Number(primary).toLocaleString()} ${section.headline}</b></div>`}).join('');
  }
  return html||`<div class="note">No player box-score statistics were available for this game.</div><div class="note" style="margin-top:8px;font-size:11px;opacity:.7">Debug: game ${gameIndex} • parsed player rows: ${(currentData?.playerGameStats||[]).filter(r=>String(r.gameIndex)===String(gameIndex)).length} • raw stat mapping: ${currentData?.statMappings?._diagnostic?.statDiagnostics?.byGame?.[String(gameIndex)]?.rawRows||0}</div>`
}
function openBoxScore(gameIndex){const g=games.find(x=>String(x.index)===String(gameIndex));if(!g)return;const players=new Map((currentData?.players||[]).map(p=>[String(p.id),p]));const away=g.awayTeamResolved||{name:g.awayName,recordIndex:g.AwayTeam};const home=g.homeTeamResolved||{name:g.homeName,recordIndex:g.HomeTeam};const winner=gameResultLabel(g);document.getElementById('boxScoreTitle').textContent=`${g.awayName} @ ${g.homeName}`;document.getElementById('boxScoreBody').innerHTML=`<div class="boxscore"><div class="boxscore-hero"><div class="note" style="text-align:center">${g.phaseLabel||'Regular Season'} • WEEK ${Number(g.phaseWeek||g.week+1)}</div><div class="boxscore-score"><div><div class="boxscore-team">${g.awayName}</div><div class="boxscore-big">${Number(g.AwayScore)||0}</div></div><div class="boxscore-vs">FINAL</div><div><div class="boxscore-team">${g.homeName}</div><div class="boxscore-big">${Number(g.HomeScore)||0}</div></div></div><div class="boxscore-winner" style="text-align:center">${winner}</div></div><div class="boxscore-section"><h3>PLAYER LEADERS</h3><div class="boxscore-grid"><div class="boxscore-team-card"><h4>${g.awayName}</h4>${renderLeaderCard(players,away,g.index)}</div><div class="boxscore-team-card"><h4>${g.homeName}</h4>${renderLeaderCard(players,home,g.index)}</div></div></div></div>`;document.getElementById('boxScoreModal').classList.add('show')}
function renderGames(){const c=document.getElementById('games');const list=currentGameSet();if(!franchiseLoaded){c.innerHTML='<div class="empty" style="grid-column:1/-1">Import your Madden 27 Franchise to load games and odds.</div>';return}if(!list.length){c.innerHTML='<div class="empty" style="grid-column:1/-1">No games found for this week.</div>';return}c.innerHTML=list.map(g=>{const l=modelLine(g);g.line=l.spread;const played=isPlayed(g);const result=played?`<div class="result"><div class="result-main"><span class="result-status">${gameResultLabel(g)}</span></div><div class="result-actions"><button class="box-btn" data-game-center="${g.index}">GAME CENTER</button><button class="box-btn" data-box-score="${g.index}">BOX SCORE</button></div></div>`:`<div class="market-board"><div class="market-team-label"><span>AWAY</span><b>${g.awayName}</b></div><div class="market-row">${market(g.awayName+' ML','Moneyline',l.awayML,g,'mlA')}${market(g.awayName+' '+(l.spread>0?'+':'')+l.spread,'Spread',(l.spread>0?'+':'')+l.spread+' '+l.awaySpread,g,'sprA',l.spread)}${market('Over '+l.total,'Total','O '+l.total+' '+l.over,g,'over',l.total)}</div><div class="market-team-label"><span>HOME</span><b>${g.homeName}</b></div><div class="market-row">${market(g.homeName+' ML','Moneyline',l.homeML,g,'mlH')}${market(g.homeName+' '+(l.spread>0?'-':'+' )+Math.abs(l.spread),'Spread',(l.spread>0?'-':'+' )+Math.abs(l.spread)+' '+l.homeSpread,g,'sprH',-l.spread)}${market('Under '+l.total,'Total','U '+l.total+' '+l.under,g,'under',l.total)}</div><div class="result-actions" style="margin-top:10px"><button class="box-btn" data-game-center="${g.index}">GAME CENTER</button></div></div>`;return `<article class="game"><div class="gamehead"><span>${g.phaseLabel||'Regular Season'} • WEEK ${Number(g.phaseWeek||g.week+1)} • GAME ${Number(g.SeasonGameNum)+1}</span><span>${String(g.DayOfWeek||'').toUpperCase()} • ${formatGameTime(g)} &nbsp; ${played?'FINAL':'UPCOMING'}</span></div><div class="teams"><div class="team">${teamLogoCell(g.awayAb,g.awayName)}<strong>${g.awayName}</strong>${played?`<div class="record" style="font-size:22px;font-weight:900;color:var(--text);margin-top:2px">${Number(g.AwayScore)||0}</div>`:`<div class="record">${l.aRec}</div>`}</div><div class="vs">@</div><div class="team">${teamLogoCell(g.homeAb,g.homeName)}<strong>${g.homeName}</strong>${played?`<div class="record" style="font-size:22px;font-weight:900;color:var(--text);margin-top:2px">${Number(g.HomeScore)||0}</div>`:`<div class="record">${l.hRec}</div>`}</div></div>${result}</article>`}).join('');c.querySelectorAll('[data-add]').forEach(b=>b.addEventListener('click',()=>{const x=JSON.parse(decodeURIComponent(b.dataset.add));x.odds=parseOddsDisplay(x.display);slip.push({...x,key:crypto.randomUUID()});saveState();renderSlip();setStatus('Selection added to bet slip.','ok')}));c.querySelectorAll('[data-box-score]').forEach(b=>b.addEventListener('click',()=>openBoxScore(b.dataset.boxScore)));c.querySelectorAll('[data-game-center]').forEach(b=>b.addEventListener('click',()=>openGameCenter(b.dataset.gameCenter)));}
function parseOddsDisplay(s){const m=String(s).match(/([+-]\d+)$/);return m?Number(m[1]):-110}
function betWeekLabel(x){const n=Number(x?.phaseWeek??(Number.isFinite(Number(x?.week))?Number(x.week)+1:NaN));return Number.isFinite(n)&&n>0?`Week ${n}`:''}
function betMatchupMeta(x,kindLabel){const wk=betWeekLabel(x);const matchup=`${betTeamName(x?.away,x?.awayName)} @ ${betTeamName(x?.home,x?.homeName)}`;return `${kindLabel}${wk?` • ${wk}`:''} • ${matchup}`}
function renderSlip(){const s=document.getElementById('slip');document.getElementById('count').textContent=slip.length;if(!slip.length){s.innerHTML='<div class="empty">Your bet slip is empty.<br><br>Click a market to add it.</div>';['betType','combined'].forEach(id=>document.getElementById(id).textContent='—');document.getElementById('profit').textContent='$0.00';document.getElementById('return').textContent='$0.00';return}s.innerHTML=slip.map(b=>`<div class="bet"><div class="bettop"><div style="display:flex;gap:8px;min-width:0"><div class="slip-team-stack">${teamLogoForName(b.away,true)}${teamLogoForName(b.home,true)}</div><div><div class="betname">${b.label}</div><div class="betmeta">${b.kind?.startsWith('prop')?betMatchupMeta(b,'PLAYER PROP'):`${b.market} • ${b.kind==='mlA'||b.kind==='sprA'?'AWAY • '+b.away:b.kind==='mlH'||b.kind==='sprH'?'HOME • '+b.home:'GAME TOTAL'} • ${betWeekLabel(b)?betWeekLabel(b)+' • ':''}${betTeamName(b.away,b.awayName)} @ ${betTeamName(b.home,b.homeName)}`}</div></div></div><button class="x" data-remove="${b.key}">×</button></div><div style="margin-top:6px;font-weight:800">${formatSavedLegDisplay(b)}</div></div>`).join('');s.querySelectorAll('[data-remove]').forEach(x=>x.addEventListener('click',()=>{slip=slip.filter(b=>b.key!==x.dataset.remove);saveState();renderSlip()}));const dec=parlayDecimalOdds(slip),w=Math.max(0,Number(document.getElementById('wager').value)||0);document.getElementById('betType').textContent=slip.length===1?'STRAIGHT':'PARLAY';document.getElementById('combined').textContent=localStorage.getItem('m27OddsFormat')==='decimal'?dec.toFixed(2):decimalToAmerican(dec);document.getElementById('profit').textContent=money(w*(dec-1));document.getElementById('return').textContent=money(w*dec)}
function playerWasInjured(playerId){
  const p=(currentData?.players||[]).find(x=>String(x.id)===String(playerId));
  if(!p)return false;
  const fields=p.injuryFields||{};
  const entries=Object.entries(fields).filter(([,v])=>v!==null&&v!==undefined&&String(v).trim()!=='');
  const statusValues=[p.injuryStatus,...entries.filter(([k])=>/status|medical|health/i.test(String(k))).map(([,v])=>v)]
    .filter(v=>v!==null&&v!==undefined&&String(v).trim()!=='')
    .map(v=>String(v).trim().toLowerCase());
  // Only explicit unavailable/injury states can void a prop. Do not treat a
  // generic field containing the word "injury" or a historical/current injury
  // description as proof that the player missed this game.
  for(const text of statusValues){
    if(/^(?:healthy|active|available|cleared|none|no injury|not injured|0|false)$/i.test(text))continue;
    if(/^(?:out|inactive|injured|injury|ir|reserve|doubtful|pup|nfi)$/i.test(text))return true;
    if(/\b(out|inactive|injured|injury reserve|injured reserve|medically unavailable|doubtful)\b/i.test(text) && !/questionable/i.test(text))return true;
  }
  return false;
}
function playerParticipatedInGame(playerId,g){
  if(!g)return false;
  const rows=(currentData?.playerGameStats||[]).filter(r=>String(r.playerId)===String(playerId)&&String(r.gameIndex)===String(g.index));
  if(!rows.length)return false;
  const participationKeys=['targets','offensiveSnaps','receptions','recYds','recTD','rushAtt','rushYds','rushTD','passYds','passTD','passInt','completions','attempts','tackles','sacks','defInt'];
  return rows.some(r=>participationKeys.some(k=>Number.isFinite(Number(r.stats?.[k]))&&Number(r.stats[k])>0));
}
function settleBet(b,g){const kind=b.kind;const a=Number(g.AwayScore)||0,h=Number(g.HomeScore)||0;let win=null;if(kind==='mlA')win=a>h;else if(kind==='mlH')win=h>a;else if(kind==='over')win=a+h>Number(b.line);else if(kind==='under')win=a+h<Number(b.line);else if(kind==='sprA')win=a+Number(b.line)>h;else if(kind==='sprH')win=h+Number(b.line)>a;else if(kind==='propOver'||kind==='propUnder'){const row=(currentData?.playerGameStats||[]).find(r=>String(r.playerId)===String(b.playerId)&&String(r.gameIndex)===String(g.index));const value=row?.stats?.[b.propStat];if(Number.isFinite(Number(value))){win=kind==='propOver'?Number(value)>Number(b.line):Number(value)<Number(b.line);b.actual=value;}else if(playerParticipatedInGame(b.playerId,g)){return 'lost';}else if(playerWasInjuredAtBet(b)||playerWasInjured(b.playerId)){return 'void';}else{return 'lost';}}else return null;return win?'won':'lost'}
function findBetGame(l){return games.find(x=>l.gameIndex!==undefined&&l.gameIndex!==null&&String(x.index)===String(l.gameIndex))||games.find(x=>gameKey(x)===l.gameId)||games.find(x=>Number(x.SeasonWeek)===Number(l.week)&&String(x.AwayTeam)===String(l.away)&&String(x.HomeTeam)===String(l.home))||null}
function settleLegForGame(l,g){return g&&isPlayed(g)?settleBet(l,g):null}
function settlePending(){if(!games.length||!history.length||!franchiseLoaded)return;const key=currentFranchiseKey();const label=currentFranchiseLabel();const year=currentData?.gameYear??null;let changed=false;for(const bet of history){if(bet.status!=='pending')continue;if(!bet.franchiseKey||bet.franchiseKey!==key){if(betBelongsToCurrentFranchise(bet)){bet.franchiseKey=key;bet.franchiseName=label;bet.franchiseYear=year;changed=true;}else continue;}const legs=bet.legs||[];const results=legs.map(l=>settleLegForGame(l,findBetGame(l)));if(results.length&&results.every(r=>r!==null)){const hasLoss=results.includes('lost');const allVoid=results.every(r=>r==='void');if(hasLoss){bet.status='lost';bet.settledAt=new Date().toISOString();bet.profit=-Number(bet.wager||0);bet.payout=0;changed=true;continue;}if(allVoid){bet.status='void';bet.settledAt=new Date().toISOString();bet.profit=0;bet.payout=bet.wager;balance+=Number(bet.wager)||0;changed=true;continue;}const activeResults=results.filter(r=>r!=='void');if(activeResults.length&&activeResults.every(r=>r==='won')){const originalOdds=Number(bet.decimalOdds)||1;const voidCount=results.filter(r=>r==='void').length;let dec=originalOdds;if(voidCount){const voidOdds=legs.map((l,i)=>results[i]==='void'?americanToDecimal(l.odds):1).reduce((v,d)=>v*d,1);dec=voidOdds>0?originalOdds/voidOdds:originalOdds;dec=Math.max(1,dec);}bet.status='won';bet.wonAt=new Date().toISOString();delete bet.settledAt;bet.decimalOdds=dec;bet.americanOdds=decimalToAmerican(dec);bet.profit=Number(bet.wager||0)*(dec-1);bet.payout=Number(bet.wager||0)*dec;changed=true;}}}if(changed){saveState();renderActiveBets();renderHistory();renderStats()}}
function reconcileLegacyVoids(){if(!games.length||!history.length||!franchiseLoaded)return;const key=currentFranchiseKey();let changed=false;for(const bet of history){if(bet.status!=='void'||!betBelongsToCurrentFranchise(bet))continue;const legs=bet.legs||[];const results=legs.map(l=>settleLegForGame(l,findBetGame(l)));if(!results.length||results.some(r=>r===null))continue;if(results.includes('lost')){const wager=Number(bet.wager)||0;bet.status='lost';bet.settledAt=new Date().toISOString();bet.profit=-wager;bet.payout=0;balance-=wager;changed=true;continue;}if(results.length&&results.every(r=>r==='won')){const wager=Number(bet.wager)||0;const dec=Number(bet.decimalOdds)||1;const profit=wager*(dec-1);bet.status='won';bet.settledAt=new Date().toISOString();bet.profit=profit;bet.payout=wager+profit;balance+=profit;changed=true;}}if(changed){balance=Math.max(0,balance);saveWallet();renderBalance();renderActiveBets();renderHistory();renderStats()}}
function injurySnapshotForPlayer(playerId){
  const p=(currentData?.players||[]).find(x=>String(x.id)===String(playerId));
  if(!p)return null;
  const fields=p.injuryFields||{};
  const statusValues=[p.injuryStatus,...Object.entries(fields)
    .filter(([k,v])=>/status|medical|health|injur/i.test(String(k))&&v!==null&&v!==undefined&&String(v).trim()!=='')
    .map(([,v])=>v)]
    .filter(v=>v!==null&&v!==undefined&&String(v).trim()!=='')
    .map(v=>String(v).trim());
  return {status:p.injuryStatus??null,values:[...new Set(statusValues)]};
}
function playerWasInjuredAtBet(leg){
  const snap=leg?.injurySnapshot;
  if(!snap)return false;
  return (snap.values||[]).some(v=>{
    const text=String(v).trim().toLowerCase();
    if(/^(?:healthy|active|available|cleared|none|no injury|not injured|0|false)$/i.test(text))return false;
    return /^(?:out|inactive|injured|injury|ir|reserve|doubtful|pup|nfi)$/i.test(text)
      || /\b(out|inactive|injured|injury reserve|injured reserve|medically unavailable|doubtful)\b/i.test(text) && !/questionable/i.test(text);
  });
}
function placeBet(){if(!slip.length){setStatus('Add a selection first.','err');return}if(!franchiseLoaded){setStatus('Import a Franchise before placing a wager.','err');return}const wager=Math.max(1,Number(document.getElementById('wager').value)||0);if(wager>balance){setStatus('Wager exceeds your available balance.','err');return}const dec=parlayDecimalOdds(slip);const legs=slip.map(x=>{const leg={...x};if(leg.playerId!==undefined&&leg.playerId!==null)leg.injurySnapshot=injurySnapshotForPlayer(leg.playerId);return leg});history.unshift({id:crypto.randomUUID(),placedAt:new Date().toISOString(),status:'pending',wager,decimalOdds:dec,americanOdds:decimalToAmerican(dec),profit:0,payout:0,franchiseName:currentFranchiseLabel(),franchiseYear:currentData?.gameYear??null,franchiseKey:currentFranchiseKey(),legs});balance-=wager;slip=[];saveWallet();evaluateChallenges();renderSlip();renderActiveBets();renderHistory();setStatus('Bet placed. Your wager has been deducted from the balance.','ok')}

function renderStandings(){const rows=teams.filter(t=>String(t.name||'').trim().toLowerCase()!=='practice').map(t=>{const s=statsForTeam(t.id);return{...t,...s}}).sort((a,b)=>(b.w-a.w)||(b.pf-b.pa)-(a.pf-a.pa));document.getElementById('standings').innerHTML=`<table class="table"><thead><tr><th>Team</th><th>W</th><th>L</th><th>T</th><th>PF</th><th>PA</th><th>Diff</th></tr></thead><tbody>${rows.map(t=>`<tr><td><div class="standings-team">${teamLogoCell(t.abbreviation||t.ab||t.shortName,t.name||t.id.slice(-8)).replace('class="logo"','class="logo" style="margin:0"')}<b>${t.name||t.id.slice(-8)}</b></div></td><td>${t.w}</td><td>${t.l}</td><td>${t.t}</td><td>${t.pf}</td><td>${t.pa}</td><td class="${t.pf-t.pa>=0?'pos':'neg'}">${t.pf-t.pa>=0?'+':''}${t.pf-t.pa}</td></tr>`).join('')}</tbody></table>`}
function betTrackerSummaryHtml(states){
  const labels={won:'HIT',lost:'MISSED',void:'VOID',pending:'PENDING'};
  const classes={won:'hit',lost:'miss',void:'void',pending:'pending'};
  return `<div class="tracker-segments">${states.map((st,i)=>`<span class="tracker-segment ${classes[st]||'pending'}" title="Leg ${i+1}: ${labels[st]||'PENDING'}"></span>`).join('')}</div>`;
}
function legTrackerHtml(l,g,status){
  const isProp=String(l.kind||'').startsWith('prop');
  const isMoneyline=l.kind==='mlA'||l.kind==='mlH';
  if(isMoneyline)return '';
  let actual=null, result=status==='pending'?'pending':status==='won'?'won':status==='void'?'void':'lost', line=Number(l.line), label='';
  if(!Number.isFinite(line))line=0;
  if(g&&isPlayed(g)){
    if(isProp){
      const row=(currentData?.playerGameStats||[]).find(r=>String(r.playerId)===String(l.playerId)&&String(r.gameIndex)===String(g.index));
      const value=row?.stats?.[l.propStat];
      if(Number.isFinite(Number(value))){actual=Number(value);label=`Actual ${actual} • Line ${line}`;}
      else if(status==='void'){label='No game stats • Injured / DNP';}
      else if(status==='lost'){label='No qualifying stat • MISSED';}
    }else if(l.kind==='over'||l.kind==='under'){
      const a=Number(g.AwayScore)||0,h=Number(g.HomeScore)||0,total=a+h;
      actual=total;label=`Actual ${total} • Line ${line}`;
    }else if(String(l.kind||'').startsWith('spr')){
      const a=Number(g.AwayScore)||0,h=Number(g.HomeScore)||0;
      const margin=l.kind==='sprA'?a-h:h-a;
      actual=margin;label=`Actual ${margin>0?'+':''}${margin} • Line ${line>0?'+':''}${line}`;
    }else{
      label='Final score';
    }
  }else if(isProp){label=result==='void'?'INJURED / DNP':`Line ${line} • Awaiting game`}
  else label=result==='void'?'VOID':'Awaiting game result';
  if(actual===null)return `<div class="bet-tracker"><div class="tracker-head"><span class="tracker-label">${label}</span><span class="tracker-status ${result}">${result==='won'?'HIT':result==='lost'?'MISSED':result==='void'?'VOID':'PENDING'}</span></div></div>`;
  const minRaw=Math.min(0,actual,line), maxRaw=Math.max(0,actual,line);
  const span=Math.max(1,maxRaw-minRaw), pad=Math.max(1,span*.15), min=minRaw-pad, max=maxRaw+pad;
  const pos=v=>Math.max(0,Math.min(100,((v-min)/(max-min))*100));
  const actualPct=pos(actual), linePct=pos(line);
  const targetStart=(l.kind==='under')?pos(min):linePct;
  const targetWidth=(l.kind==='under')?Math.max(0,linePct-targetStart):Math.max(0,100-linePct);
  const progressLeft=0, progressWidth=Math.max(0,actualPct-progressLeft);
  const actualText=(actual>0?`+${actual}`:String(actual));
  const lineText=(line>0?`+${line}`:String(line));
  return `<div class="bet-tracker"><div class="tracker-head"><span class="tracker-label">ACTUAL ${actualText} / LINE ${lineText}</span><span class="tracker-status ${result}">${result==='won'?'HIT':result==='lost'?'MISSED':result==='void'?'VOID':'PENDING'}</span></div><div class="tracker-visual"><div class="tracker-track"><span class="tracker-target-zone ${l.kind==='under'?'under':'over'}" style="left:${targetStart}%;width:${targetWidth}%"></span><span class="tracker-progress ${result}" style="left:${progressLeft}%;width:${progressWidth}%"></span><span class="tracker-line-marker" style="left:${linePct}%"></span><span class="tracker-actual-marker ${result}" style="left:${actualPct}%"></span></div></div><div class="tracker-scale"><span class="actual-label ${result}" style="left:${actualPct}%">${actualText}</span><span class="line-label" style="left:${linePct}%">${lineText}</span></div></div>`;
}
function betLegState(b,l){const g=findBetGame(l);if(!g||!isPlayed(g))return 'pending';const copy={...l};const r=settleBet(copy,g);return r==='won'?'won':r==='lost'?'lost':r==='void'?'void':'pending'}
function activeBetsHtml(active){return active.map(b=>{const gamesText=[...new Set((b.legs||[]).map(l=>`${betTeamName(l.away,l.awayName)} @ ${betTeamName(l.home,l.homeName)}`))].join(' • ');const first=b.legs?.[0]||{};const firstAway=betTeamName(first.away,first.awayName);const firstHome=betTeamName(first.home,first.homeName);const states=(b.legs||[]).map(l=>betLegState(b,l));const wins=states.filter(x=>x==='won').length;const losses=states.filter(x=>x==='lost').length;const voids=states.filter(x=>x==='void').length;const pending=states.filter(x=>x==='pending').length;const status=losses?'lost':pending?'pending':(wins>0?'won':'void');const cashout=estimateCashout(b);const isParlay=(b.legs||[]).length>1;const legsHtml=(b.legs||[]).map((l,i)=>{const g=findBetGame(l);const st=states[i];return `<div class="active-leg-group"><div class="active-leg"><span style="display:flex;align-items:center;gap:7px">${teamLogoForName(betTeamName(l.away,l.awayName),true)}${teamLogoForName(betTeamName(l.home,l.homeName),true)}<span>${l.label}</span></span><b>${formatSavedLegDisplay(l)}</b></div>${legTrackerHtml(l,g,st)}</div>`}).join('');return `<article class="active-card"><div class="active-card-head"><div style="min-width:0"><div style="display:flex;align-items:center;gap:9px"><div class="active-match-logos">${teamLogoForName(firstAway,true)}${teamLogoForName(firstHome,true)}</div><div style="min-width:0"><div class="active-title">${isParlay?`${b.legs.length}-Leg Parlay`:'Straight Bet'}</div><div class="active-game">${gamesText}</div></div></div><div class="save-badge" title="Franchise save used when this wager was placed">FRANCHISE SAVE <b>${betSaveLabel(b)}</b></div></div><span class="active-status ${status}">${status==='won'?'WON':status==='lost'?'LOST':status==='void'?'VOID':'PENDING'}</span></div>${betTrackerSummaryHtml(states)}${isParlay?`<details class="active-legs-toggle"><summary><span>SHOW ${b.legs.length} LEGS</span><span>${wins} hit${wins===1?'':'s'} • ${losses} missed${voids?` • ${voids} void`:''}</span></summary><div class="active-legs">${legsHtml}</div></details>`:`<div class="active-legs">${legsHtml}</div>`}<div class="active-foot"><span>Wager <b>${money(b.wager)}</b></span><span>Combined odds <b>${fmtOdds(b.americanOdds||decimalToAmerican(Number(b.decimalOdds)||1))}</b></span><span>${status==='won'?'Return':status==='lost'?'P/L':status==='void'?'Refund':'Potential return'} <b>${status==='won'?money(b.payout||b.wager*(b.decimalOdds||1)):status==='lost'?money(b.profit||-b.wager):status==='void'?money(b.payout||b.wager):money(b.wager*(b.decimalOdds||1))}</b></span><button class="btn" data-view-slip="${b.id}">View Slip</button>${status==='pending'?`<button class="cashout-btn" data-cashout-bet="${b.id}">Cash Out ${money(cashout)}</button>`:status==='lost'&&b.status==='pending'?`<button class="cashout-btn" data-cashout-bet="${b.id}">Cash Out $0.00 • Remove</button>`:status==='won'?`<button class="cashout-btn collect-winnings-btn" data-collect-winnings="${b.id}">Collect Winnings ${money(b.payout||0)}</button>`:''}</div>${status==='pending'?'<div class="cashout-note">Estimated cash out • based on the original odds and completed legs; no live market feed is available.</div>':status==='won'?'<div class="cashout-note">Wager won. Review the winning slip, then collect the payout to move it to Bet History.</div>':''}</article>`}).join('')}
function estimateCashout(b){if(!b||b.status!=='pending')return 0;const legs=b.legs||[];let locked=Number(b.wager)||0;let pending=0;for(const l of legs){const g=findBetGame(l);if(g&&isPlayed(g)){const copy={...l};const r=settleBet(copy,g);if(r==='won')locked*=americanToDecimal(l.odds);else if(r==='lost')return 0;}else pending++}if(!pending)return Math.min(Number(b.wager||0)*(Number(b.decimalOdds)||1),Math.max(0,locked));const pendingDecimals=legs.filter(l=>{const g=findBetGame(l);return !(g&&isPlayed(g))}).map(l=>americanToDecimal(l.odds));const implied=pendingDecimals.reduce((v,d)=>v*(1/Math.max(d,1)),1);const marketFactor=Math.max(.45,Math.min(.9,.72+implied*.18));const value=locked*marketFactor;return Math.max(0,Math.min(Number(b.wager||0)*(Number(b.decimalOdds)||1)*.9,value))}
function cashOutBet(id){const bet=history.find(b=>b.id===id);if(!bet||bet.status!=='pending')return;let amount=Number(estimateCashout(bet));if(!Number.isFinite(amount)||amount<0)amount=0;const zeroRemoval=amount<=0;amount=zeroRemoval?0:amount;const ok=confirm(zeroRemoval?`Cash out this stuck/lost wager for $0.00?\n\nIt will be removed from Active Bets and kept in Bet History. No refund will be issued.`:`Cash out this wager for ${money(amount)}?\n\nThis is an estimated cash-out value based on the saved wager data, not a live sportsbook price.`);if(!ok)return;bet.status='cashed_out';bet.cashoutAt=new Date().toISOString();bet.settledAt=bet.cashoutAt;bet.cashoutAmount=amount;bet.profit=amount-Number(bet.wager||0);bet.payout=amount;if(amount>0)balance+=amount;saveWallet();saveState();renderActiveBets();renderHistory();renderStats();renderBalance();setStatus(zeroRemoval?'Wager removed with a $0.00 cash out. No refund was issued.':`Bet cashed out for ${money(amount)}.`,'ok')}function collectWinnings(id){const bet=history.find(b=>b.id===id);if(!bet||bet.status!=='won'||bet.collectedAt)return;const amount=Number(bet.payout||0);if(amount<=0){setStatus('Winnings are not available on this wager.','err');return}bet.collectedAt=new Date().toISOString();bet.settledAt=bet.collectedAt;balance+=amount;saveWallet();saveState();renderActiveBets();renderHistory();renderStats();renderBalance();setStatus(`Winnings collected: ${money(amount)} added to your bankroll.`,'ok')}
function cancelBet(id){const bet=history.find(b=>b.id===id);if(!bet||bet.status!=='pending')return;const ok=confirm(`Cancel this wager for ${money(bet.wager)}?\n\nThe full wager amount will be refunded to your bankroll.`);if(!ok)return;bet.status='cancelled';bet.cancelledAt=new Date().toISOString();bet.settledAt=bet.cancelledAt;bet.profit=0;bet.payout=0;balance+=Number(bet.wager)||0;saveWallet();saveState();renderActiveBets();renderHistory();renderStats();renderBalance();setStatus(`Bet cancelled. ${money(bet.wager)} refunded to your bankroll.`,'ok')}
function bindViewSlipButtons(root){root.querySelectorAll('[data-view-slip]').forEach(btn=>btn.addEventListener('click',()=>openHistorySlip(btn.dataset.viewSlip)));root.querySelectorAll('[data-cashout-bet]').forEach(btn=>btn.addEventListener('click',()=>cashOutBet(btn.dataset.cashoutBet)));root.querySelectorAll('[data-collect-winnings]').forEach(btn=>btn.addEventListener('click',()=>collectWinnings(btn.dataset.collectWinnings)));}
function assignPropDepth(players){const groups=new Map();for(const p of players){const k=`${p.team||p.side}|${propPositionKey(p.position)}`;if(k.endsWith('|OTHER'))continue;const arr=groups.get(k)||[];arr.push(p);groups.set(k,arr)}for(const [k,arr] of groups){const pos=k.split('|').pop();arr.sort((a,b)=>{const ar=Number(a.depthRank),br=Number(b.depthRank),av=Number.isInteger(ar)&&ar>0,bv=Number.isInteger(br)&&br>0;if(av!==bv)return av?-1:1;if(av&&bv&&ar!==br)return ar-br;return String(a.name||'').localeCompare(String(b.name||''))});arr.forEach(p=>{const n=Number(p.depthRank),valid=Number.isInteger(n)&&n>0;const label=String(p.depthPosition||p.position||pos).toUpperCase();p.role=valid?`${label}${n}`:'UNRANKED';p.roleText=valid?(n===1?'STARTER':n===2?'ROTATION':'DEPTH'):'DEPTH CHART UNAVAILABLE'})}return players}
function openHistorySlip(id){const b=history.find(x=>x.id===id);if(!b)return;document.getElementById('slipModalTitle').textContent=`${b.status.toUpperCase()} • ${b.legs?.length>1?'PARLAY':'STRAIGHT'} • ${betSaveLabel(b)}`;const body=document.getElementById('slipModalBody');const states=(b.legs||[]).map(l=>betLegState(b,l));const status=b.status==='pending'?(states.includes('lost')?'lost':states.includes('pending')?'pending':states.includes('won')?'won':'void'):b.status;const cashout=estimateCashout(b);body.innerHTML=`<div class="save-badge" style="margin-top:0;margin-bottom:8px">FRANCHISE SAVE <b>${betSaveLabel(b)}</b></div><div class="hero" style="margin-bottom:10px"><div class="tracker-head"><span class="eyebrow">BET TRACKER</span><span class="active-status ${status==='won'?'won':status==='lost'?'lost':'pending'}">${status.toUpperCase()}</span></div>${betTrackerSummaryHtml(states)}<div class="tracker-stats"><span>${b.legs?.length||0} leg${b.legs?.length===1?'':'s'}</span><b>${status==='won'?money(b.payout):status==='lost'?money(b.profit):money(b.wager*(b.decimalOdds||1))}</b></div></div>${(b.legs||[]).map((l,i)=>{const g=findBetGame(l);const st=states[i];return `<div class="slip-leg"><div style="display:flex;justify-content:space-between;gap:10px"><div style="display:flex;align-items:center;gap:8px"><div class="slip-team-stack">${teamLogoForName(betTeamName(l.away,l.awayName),true)}${teamLogoForName(betTeamName(l.home,l.homeName),true)}</div><b>${l.label}</b></div><b class="${st==='won'?'hit':st==='lost'?'miss':st==='void'?'void':''}">${st==='won'?'✓ HIT':st==='lost'?'✗ MISSED':st==='void'?'VOID':'PENDING'}</b></div><div class="betmeta">${l.kind?.startsWith('prop')?betMatchupMeta(l,'PLAYER PROP'):`${l.market} • ${l.kind==='over'||l.kind==='under'?'GAME TOTAL':l.kind?.startsWith('spr')?'SPREAD':'MONEYLINE'} • ${betWeekLabel(l)?betWeekLabel(l)+' • ':''}${betTeamName(l.away,l.awayName)} @ ${betTeamName(l.home,l.homeName)}`}</div><div style="margin-top:6px;font-weight:800">${formatSavedLegDisplay(l)}</div>${legTrackerHtml(l,g,st)}</div>`}).join('')}<div class="history-summary"><span>Wager <b>${money(b.wager)}</b></span><span>Odds <b>${fmtOdds(b.americanOdds)}</b></span><span>${b.status==='pending'?'Potential return':b.status==='won'?'Payout':b.status==='cashed_out'?'Cash out':'P/L'} <b>${b.status==='pending'?money(b.wager*(b.decimalOdds||1)):b.status==='won'?money(b.payout):b.status==='cashed_out'?money(b.cashoutAmount):money(b.profit)}</b></span></div>${b.status==='pending'?`<div style="display:flex;justify-content:flex-end;margin-top:12px"><button class="cashout-btn" data-cashout-bet="${b.id}">Cash Out ${money(cashout)}</button></div><div class="cashout-note">Estimated cash out based on saved odds and completed legs. There is no live market feed in the offline prototype.</div>`:b.status==='won'&&!b.collectedAt?`<div style="display:flex;justify-content:flex-end;margin-top:12px"><button class="cashout-btn collect-winnings-btn" data-collect-winnings="${b.id}">Collect Winnings ${money(b.payout||0)}</button></div><div class="cashout-note">Winning payout is ready to collect. Collect it to add the money to your bankroll and move the wager to Bet History.</div>`:b.status==='won'&&b.collectedAt?`<div class="cashout-note">✓ Winnings collected. ${money(b.payout||0)} was already added to your bankroll.</div>`:''}`;body.querySelectorAll('[data-cashout-bet]').forEach(btn=>btn.addEventListener('click',()=>{cashOutBet(btn.dataset.cashoutBet);if(history.find(x=>x.id===btn.dataset.cashoutBet)?.status!=='pending')document.getElementById('slipModal').classList.remove('show')}));body.querySelectorAll('[data-collect-winnings]').forEach(btn=>btn.addEventListener('click',()=>{collectWinnings(btn.dataset.collectWinnings);if(history.find(x=>x.id===btn.dataset.collectWinnings)?.status!=='won')document.getElementById('slipModal').classList.remove('show')}));document.getElementById('slipModal').classList.add('show')}
function compareStatForPosition(position){const pos=String(position||'').toUpperCase();if(pos==='QB')return {key:'passYds',label:'Pass Yds'};if(['HB','RB','FB'].includes(pos))return {key:'rushYds',label:'Rush Yds'};if(['WR','TE'].includes(pos))return {key:'recYds',label:'Rec Yds'};if(['OL','LT','LG','C','RG','RT'].includes(pos))return {key:'pancakes',label:'Pancakes'};return {key:'tackles',label:'Tackles'}}
function openPlayerCompare(playerId){const p=(currentData?.players||[]).find(x=>String(x.id)===String(playerId));if(!p)return;const target=compareStatForPosition(p.position);const stats=currentData?.playerGameStats||[];const byPlayer=new Map();for(const r of stats){const id=String(r.playerId);const v=Number(r.stats?.[target.key]);if(!Number.isFinite(v))continue;let row=byPlayer.get(id);if(!row){row={games:new Set(),total:0};byPlayer.set(id,row)};row.games.add(String(r.gameIndex));row.total+=v}const candidates=(currentData?.players||[]).filter(x=>String(x.position||'').toUpperCase()===String(p.position||'').toUpperCase()).map(x=>{const a=byPlayer.get(String(x.id));return {...x,played:a?a.games.size:0,total:a?a.total:0}}).filter(x=>x.played>0).sort((a,b)=>b.total-a.total);const chosen=[];const seen=new Set();const add=x=>{if(!x||seen.has(String(x.id)))return;seen.add(String(x.id));chosen.push(x)};add(p);for(const x of candidates)add(x);const rows=chosen.slice(0,5).map(x=>{const a=byPlayer.get(String(x.id));const avg=a&&a.played?a.total/a.played:null;const m=(currentData?.playerProps||[]).find(z=>String(z.playerId)===String(x.id)&&String(z.stat)===target.key)||((currentData?.playerProps||[]).find(z=>String(z.playerId)===String(x.id)));let hit=null;if(m&&a&&a.played){const vals=stats.filter(r=>String(r.playerId)===String(x.id)).map(r=>Number(r.stats?.[m.stat])).filter(Number.isFinite);if(vals.length&&Number.isFinite(Number(m.line)))hit=Math.round(vals.filter(v=>m.over?v>Number(m.line):v<Number(m.line)).length/vals.length*100)}return `<tr><td><b>${escapeHtml(x.name)}</b>${String(x.id)===String(p.id)?' <span class="social-badge">YOU</span>':''}</td><td>${escapeHtml(x.teamName||x.team||'')}</td><td>${escapeHtml(x.position||'')}</td><td>${a?.played||0}</td><td>${avg==null?'—':avg.toFixed(1)}</td><td>${m?Number(m.line).toFixed(1):'—'}</td><td>${hit==null?'—':hit+'%'}</td></tr>`}).join('');document.getElementById('compareTitle').textContent=`${p.name} • ${target.label} comparison`;document.getElementById('compareBody').innerHTML=`<div class="compare-picker"><span class="tag">${escapeHtml(p.name)}</span><span class="note">Compared with ${target.label} leaders at the same position who have recorded playing time in this Franchise.</span></div><table class="compare-table"><thead><tr><th>Player</th><th>Team</th><th>Pos</th><th>GP</th><th>Avg</th><th>Line</th><th>Hit %</th></tr></thead><tbody>${rows||'<tr><td colspan="7">No played players available for comparison.</td></tr>'}</tbody></table>`;document.getElementById('playerProfileModal').classList.remove('show');document.getElementById('compareModal').classList.add('show')}

function propPositionKey(position){const p=String(position||'').toUpperCase();if(p==='HB'||p==='FB'||p==='RB')return 'RB';if(p==='WR')return 'WR';if(p==='TE')return 'TE';if(p==='QB')return 'QB';return 'OTHER'}
function propSectionLabel(key){return key==='QB'?'QUARTERBACKS':key==='RB'?'RUNNING BACKS':key==='WR'?'WIDE RECEIVERS':key==='TE'?'TIGHT ENDS':'OTHER'}
function renderHistory(){const c=document.getElementById('history');const currentBets=franchiseLoaded?history.filter(b=>betBelongsToCurrentFranchise(b)):[];const active=currentBets.filter(b=>b.status==='pending'||(b.status==='won'&&!b.collectedAt));const activeWrap=document.getElementById('historyActiveBets');const activeCount=document.getElementById('historyActiveBetCount');if(activeCount)activeCount.textContent=`${active.length} open wager${active.length===1?'':'s'}`;if(activeWrap)activeWrap.innerHTML=active.length?`<div class="active-stack">${activeBetsHtml(active)}</div>`:'<div class="empty">No active bets.</div>';if(activeWrap)bindViewSlipButtons(activeWrap);const settled=currentBets.filter(b=>b.status!=='pending'&&!(b.status==='won'&&!b.collectedAt));const count=document.getElementById('settledBetCount');if(count)count.textContent=`${settled.length} settled wager${settled.length===1?'':'s'}`;if(!settled.length){c.innerHTML='<div class="empty">No settled bets yet.</div>';return}c.innerHTML=`<table class="table"><thead><tr><th>Date</th><th>Franchise Save</th><th>Type</th><th>Odds</th><th>Wager</th><th>Status</th><th>P/L</th><th></th></tr></thead><tbody>${settled.map(b=>`<tr><td>${new Date(b.placedAt).toLocaleString()}</td><td><span class="${betSaveClass(b)}" title="${betSaveLabel(b)}">${betSaveLabel(b)}</span></td><td><div class="history-team-stack">${(b.legs||[]).slice(0,1).map(l=>teamLogoForName(betTeamName(l.away,l.awayName),true)+teamLogoForName(betTeamName(l.home,l.homeName),true)).join('')}<span>${b.legs?.length>1?'Parlay':'Straight'}</span></div></td><td>${b.americanOdds}</td><td>${money(b.wager)}</td><td class="${b.status==='won'?'pos':b.status==='lost'?'neg':b.status==='cancelled'?'':b.status==='cashed_out'?'pos':''}">${b.status.toUpperCase()}</td><td class="${b.profit>=0?'pos':'neg'}">${money(b.profit)}</td><td><button class="btn" data-view-slip="${b.id}">View Slip</button></td></tr>`).join('')}</tbody></table>`;bindViewSlipButtons(c)}
function renderStats(){const c=document.getElementById('statsContent');if(!c)return;if(!franchiseLoaded){c.innerHTML='<div class="empty">Import a Franchise first to view sportsbook statistics.</div>';return}const bets=history.filter(b=>betBelongsToCurrentFranchise(b));const active=bets.filter(b=>b.status==='pending'||(b.status==='won'&&!b.collectedAt));const cancelled=bets.filter(b=>b.status==='cancelled');const cashedOut=bets.filter(b=>b.status==='cashed_out');const settled=bets.filter(b=>['lost','void'].includes(b.status)||(['won'].includes(b.status)&&!!b.settledAt));const wins=settled.filter(b=>b.status==='won');const losses=bets.filter(b=>b.status==='lost');const wagered=settled.reduce((n,b)=>n+Number(b.wager||0),0);const payouts=wins.reduce((n,b)=>n+Number(b.payout||0),0);const profit=settled.reduce((n,b)=>n+Number(b.profit||0),0);const roi=wagered?profit/wagered*100:0;const winRate=settled.length?wins.length/settled.length*100:0;const avg=wagered/Math.max(1,settled.length);const biggestWin=wins.reduce((m,b)=>Math.max(m,Number(b.profit||0)),0);const biggestLoss=losses.reduce((m,b)=>Math.min(m,Number(b.profit||0)),0);const straight=settled.filter(b=>(b.legs||[]).length<=1).length;const parlays=settled.filter(b=>(b.legs||[]).length>1).length;const recent=settled.slice().sort((a,b)=>new Date(b.settledAt||b.placedAt)-new Date(a.settledAt||a.placedAt)).slice(0,10);const form=recent.map(b=>`<span class="stat-form ${b.status==='won'?'win':b.status==='lost'?'loss':'void'}">${b.status==='won'?'W':b.status==='lost'?'L':'V'}</span>`).join('');c.innerHTML=`<div class="cards stats-cards"><div class="mini"><div class="note">TOTAL BETS</div><b>${bets.length}</b><div class="note">${active.length} active • ${cashedOut.length} cashed out • ${cancelled.length} cancelled</div></div><div class="mini"><div class="note">RECORD</div><b>${wins.length}-${losses.length}</b><div class="note">${winRate.toFixed(1)}% win rate</div></div><div class="mini"><div class="note">NET PROFIT / LOSS</div><b class="${profit>=0?'pos':'neg'}">${money(profit)}</b><div class="note">${roi.toFixed(1)}% ROI</div></div></div><div class="cards stats-cards"><div class="mini"><div class="note">TOTAL WAGERED</div><b>${money(wagered)}</b><div class="note">Settled wagers only</div></div><div class="mini"><div class="note">TOTAL PAYOUTS</div><b>${money(payouts)}</b><div class="note">Winning returns</div></div><div class="mini"><div class="note">AVERAGE WAGER</div><b>${money(avg)}</b><div class="note">Per settled bet</div></div></div><div class="stats-grid"><article class="hero"><div class="eyebrow">BETTING BREAKDOWN</div><div class="stats-list"><div><span>Wins</span><b class="pos">${wins.length}</b></div><div><span>Losses</span><b class="neg">${losses.length}</b></div><div><span>Cash outs</span><b>${cashedOut.length}</b></div><div><span>Cancelled</span><b>${cancelled.length}</b></div><div><span>Pending</span><b>${active.length}</b></div><div><span>Straight bets</span><b>${straight}</b></div><div><span>Parlays</span><b>${parlays}</b></div><div><span>Biggest win</span><b class="pos">${money(biggestWin)}</b></div><div><span>Biggest loss</span><b class="neg">${money(biggestLoss)}</b></div></div></article><article class="hero"><div class="eyebrow">RECENT FORM</div><div class="form-row">${form||'<span class="note">No settled wagers yet.</span>'}</div><div class="note" style="margin-top:14px">Latest ${recent.length} settled wagers, newest first.</div><div class="stats-progress"><span style="width:${Math.max(0,Math.min(100,winRate))}%"></span></div><div class="note">Win rate: ${winRate.toFixed(1)}%</div></article></div><div class="analytics-grid"><article class="hero"><div class="eyebrow">MARKET PERFORMANCE</div><table class="analytics-table">${(()=>{const rows={};for(const b of settled){const type=(b.legs||[]).length>1?'Parlays':(b.legs?.[0]?.kind?.startsWith('prop')?'Player Props':'Game Bets');rows[type]??={bets:0,wins:0,profit:0};rows[type].bets++;if(b.status==='won')rows[type].wins++;rows[type].profit+=Number(b.profit||0)}return Object.entries(rows).map(([k,v])=>`<tr><td>${k}</td><td>${v.wins}/${v.bets} • ${money(v.profit)}</td></tr>`).join('')||'<tr><td>No settled data</td><td>—</td></tr>'})()}</table></article><article class="hero"><div class="eyebrow">PROFIT TREND</div><div class="form-row">${recent.slice().reverse().map(b=>`<span class="stat-form ${b.status==='won'?'win':b.status==='lost'?'loss':'void'}" title="${money(b.profit)}">${b.status==='won'?'W':b.status==='lost'?'L':'V'}</span>`).join('')||'<span class="note">No settled wagers yet.</span>'}</div><div class="note" style="margin-top:9px">Latest settled results, oldest to newest.</div></article></div><div class="dashboard-grid"><article class="dashboard-card"><div class="note">CURRENT BANKROLL</div><b>${money(balance)}</b><div class="note">Available to wager</div></article><article class="dashboard-card"><div class="note">REPUTATION</div><b>${reputationFor(settled.length,wins.length)}</b><div class="note">Based on settled volume + win rate</div></article><article class="dashboard-card"><div class="note">BIGGEST WIN</div><b>${money(biggestWin)}</b><div class="note">Single wager profit</div></article></div><div class="hero" style="margin-top:12px"><div class="eyebrow">SEASON + STREAKS</div><div class="season-grid"><div class="season-card"><div class="note">SPORTSBOOK SEASON</div><b>Season ${Math.max(1,Math.floor(Number(document.getElementById('week')?.value||1)/18)+1)}</b><div class="note">Week ${Number(document.getElementById('week')?.value||1)} • ${settled.length} settled bets</div></div><div class="season-card"><div class="note">CURRENT STREAK</div><b>${betStreaks().current}${betStreaks().currentType==='W'?' W':' L'}</b><div class="note">Best streak: ${betStreaks().best}</div></div><div class="season-card"><div class="note">SEASON PROFIT</div><b class="${profit>=0?'pos':'neg'}">${money(profit)}</b><div class="note">Career sportsbook performance</div></div></div></div><div class="hero" style="margin-top:12px"><div class="eyebrow">BETTING HEATMAP</div><div class="heatmap"><div>MARKET</div><div>WIN %</div><div>RECORD</div><div>PROFIT</div>${(()=>{const rows={};for(const b of settled){const k=betMarketType(b);rows[k]??={w:0,n:0,p:0};rows[k].n++;if(b.status==='won')rows[k].w++;rows[k].p+=Number(b.profit||0)}return Object.entries(rows).map(([k,v])=>{const r=v.n?v.w/v.n*100:0;const cls=r>=60?'heat-good':r<50?'heat-bad':'heat-neutral';return `<div>${k}</div><div class="${cls}">${r.toFixed(1)}%</div><div>${v.w}-${v.n-v.w}</div><div class="${v.p>=0?'pos':'neg'}">${money(v.p)}</div>`}).join('')||'<div>No settled markets yet.</div>'})()}</div></div><div class="hero"><div class="eyebrow">WHAT THE NUMBERS MEAN</div><div class="note">Net profit is your winnings minus settled wagers lost. ROI is net profit divided by total settled amount wagered. Cancelled wagers are refunded and excluded from performance metrics. Cashed-out wagers record the cash-out amount separately and are also excluded from win/loss performance.</div></div>`}
function renderActiveBets(){const c=document.getElementById('activeBets');const count=document.getElementById('activeBetCount');const active=franchiseLoaded?history.filter(b=>(b.status==='pending'||(b.status==='won'&&!b.collectedAt))&&betBelongsToCurrentFranchise(b)):[];if(count)count.textContent=`${active.length} open wager${active.length===1?'':'s'}`;if(!active.length){c.innerHTML='<div class="empty">No active bets. Place a wager and it will appear here until the Franchise result is available.</div>';return}c.innerHTML=`<div class="active-stack">${activeBetsHtml(active)}</div>`;bindViewSlipButtons(c)}
function openPropResearch(playerId,stat,gameIndex){const p=(currentData?.players||[]).find(x=>String(x.id)===String(playerId));const g=games.find(x=>String(x.index)===String(gameIndex));const m=(currentData?.playerProps||[]).find(x=>String(x.playerId)===String(playerId)&&x.stat===stat);if(!p||!m)return;const r=propResearchData(playerId,stat,g);const label=m.label||stat;const last=r.last5.length?r.last5.map(v=>`<span>${Number(v).toFixed(v%1?1:0)}</span>`).join(''):'<span>No sample</span>';const hitRate=r.last5.length&&Number.isFinite(r.line)?Math.round(r.hits/r.last5.length*100):null;document.getElementById('researchTitle').textContent=`${p.name} • ${label}`;document.getElementById('researchBody').innerHTML=`<div class="save-badge">${escapeHtml(g?`Week ${Number(g.phaseWeek??g.week+1)} • ${g.awayName} @ ${g.homeName}`:'Player Research')}</div><div class="research-grid"><div class="research-card"><div class="note">LINE</div><b>${Number(m.line).toFixed(1)}</b><div class="note">${fmtOdds(propOdds(m,'over'))} over • ${fmtOdds(propOdds(m,'under'))} under</div></div><div class="research-card"><div class="note">SEASON AVG</div><b>${r.seasonAvg!==null?r.seasonAvg.toFixed(1):Number(m.average).toFixed(1)}</b><div class="note">${m.games||r.vals.length} game sample</div></div><div class="research-card"><div class="note">LAST 5 HIT RATE</div><b>${hitRate!==null?hitRate+'%':'—'}</b><div class="note">${hitRate!==null?`${r.hits} over / ${r.unders} under`: 'Not enough historical data'}</div></div></div><div class="hero" style="margin-top:12px"><div class="eyebrow">RECENT RESULTS</div><div class="research-form">${last}</div><div class="note" style="margin-top:9px">Actual stat results from the imported Franchise. Green means the result reached the current line; red means it stayed below it.</div></div><div class="hero" style="margin-top:12px"><div class="eyebrow">WHY THIS LINE?</div><div class="note">${r.seasonAvg!==null?`The current line is ${Math.abs(Number(m.line)-Number(r.seasonAvg)).toFixed(1)} ${Number(m.line)>=Number(r.seasonAvg)?'above':'below'} the season average.`:'Not enough historical data for line context.'} ${r.last5.length?`Last 5 results: ${r.last5.map(v=>Number(v).toFixed(1)).join(' • ')}.`:''}</div></div><div class="hero" style="margin-top:12px"><div class="eyebrow">MATCHUP</div><div class="note">${g?`${g.phaseLabel||'Regular Season'} • Week ${Number(g.phaseWeek??g.week+1)} • ${String(g.DayOfWeek||'').toUpperCase()} ${formatGameTime(g)} • ${g.awayName} @ ${g.homeName}`:'No game attached'}</div></div>`;document.getElementById('researchModal').classList.add('show')}
function openGameCenter(gameIndex){const g=games.find(x=>String(x.index)===String(gameIndex));if(!g)return;const l=modelLine(g);const played=isPlayed(g);const teamKeys=[g.awayName,g.homeName,g.awayTeamResolved?.name,g.homeTeamResolved?.name].filter(Boolean).map(v=>String(v).toLowerCase().replace(/[^a-z0-9]/g,''));const props=(currentData?.playerProps||[]).filter(p=>{const ti=String(p.teamIndex??'');const indexMatch=ti&&[String(g.awayTeamResolved?.TeamIndex??''),String(g.homeTeamResolved?.TeamIndex??'')].includes(ti);const pk=String(p.teamName||'').toLowerCase().replace(/[^a-z0-9]/g,'');return indexMatch||(pk&&teamKeys.includes(pk));}).slice(0,10);const gameRows=(currentData?.playerGameStats||[]).filter(r=>Number(r.gameIndex)===Number(g.index));const playerMap=new Map((currentData?.players||[]).map(p=>[String(p.id),p]));const keyStats=['passYds','passTD','rushYds','rushTD','rushAtt','recYds','recTD','receptions','targets','tackles','sacks'];const leaders=[];for(const r of gameRows){const p=playerMap.get(String(r.playerId));if(!p)continue;const vals=keyStats.map(k=>({k,v:Number(r.stats?.[k])})).filter(x=>x.v>0).sort((a,b)=>b.v-a.v).slice(0,2);if(vals.length)leaders.push({name:p.name,team:p.teamName||'',stats:vals})}leaders.sort((a,b)=>(b.stats[0]?.v||0)-(a.stats[0]?.v||0));const keyStatRows=played?(leaders.slice(0,8).map(x=>`<div class="game-market-row"><span>${escapeHtml(x.name)} <small>${escapeHtml(x.team)}</small></span><b>${x.stats.map(z=>`${prettyStatName(z.k)} ${z.v}`).join(' • ')}</b></div>`).join('')||'<div class="note">No player statistics were linked to this completed game.</div>'):(props.length?props.map(m=>`<div class="game-market-row"><span>${escapeHtml(m.name)} ${escapeHtml(m.label)}</span><b>${Number(m.line).toFixed(1)}</b></div>`).join(''):'<div class="note">No player markets available.</div>');const marketRows=played?`<div class="game-market-row"><span>FINAL</span><b>${Number(g.AwayScore)||0} - ${Number(g.HomeScore)||0}</b></div>`:`<div class="game-market-row"><span>${g.awayName} ML</span><b>${fmtOdds(l.awayML)}</b></div><div class="game-market-row"><span>${g.homeName} ML</span><b>${fmtOdds(l.homeML)}</b></div><div class="game-market-row"><span>Spread</span><b>${l.spread>0?'+'+l.spread:l.spread}</b></div><div class="game-market-row"><span>Total</span><b>${l.total}</b></div>`;document.getElementById('gameCenterTitle').textContent=`${g.awayName} @ ${g.homeName}`;document.getElementById('gameCenterBody').innerHTML=`<div class="hero"><div class="eyebrow">${g.phaseLabel||'REGULAR SEASON'} • WEEK ${Number(g.phaseWeek??g.week+1)}</div><h3 style="margin:4px 0">${g.awayName} @ ${g.homeName}</h3><div class="note">${String(g.DayOfWeek||'').toUpperCase()} • ${formatGameTime(g)} • ${played?'FINAL':'UPCOMING'}</div></div><div class="game-center-grid" style="margin-top:12px"><article class="game-center-card"><h3>${played?'FINAL SCORE':'GAME MARKETS'}</h3>${marketRows}</article><article class="game-center-card"><h3>${played?'KEY PLAYER STATS':'TOP PLAYER MARKETS'}</h3>${keyStatRows}</article></div>${played?`<div style="display:flex;justify-content:flex-end;margin-top:12px"><button class="btn primary" id="gameCenterBoxBtn">OPEN BOX SCORE</button></div>`:''}`;document.getElementById('gameCenterModal').classList.add('show');document.getElementById('gameCenterBoxBtn')?.addEventListener('click',()=>{document.getElementById('gameCenterModal').classList.remove('show');openBoxScore(gameIndex)})}

function achievementData(){
 const bets=challengeHistory();const settled=bets.filter(b=>['won','lost','void'].includes(b.status));const wins=bets.filter(b=>b.status==='won');const props=wins.filter(b=>(b.legs||[]).some(l=>l.kind?.startsWith('prop')));const parlays=wins.filter(b=>(b.legs||[]).length>1);const longshots=wins.filter(b=>Number(b.americanOdds)>=200);const maxLegs=Math.max(0,...wins.map(b=>(b.legs||[]).length));const totalWagered=settled.reduce((n,b)=>n+Number(b.wager||0),0);const biggestWin=Math.max(0,...wins.map(b=>Number(b.profit||0)));const net=settled.reduce((n,b)=>n+Number(b.profit||0),0);
 const tier=(icon,title,metric,desc,targets)=>targets.map((t,i)=>({icon,title:`${title} ${['I','II','III','IV','V'][i]}`,desc:`${desc} ${t.toLocaleString()}.`,ok:metric>=t}));
 return [
  ...tier('🏆','Winning Season',wins.length,'Win wagers', [1,10,25,50,100]),
  ...tier('🎯','Prop Specialist',props.length,'Win player-prop wagers', [5,25,50,100,200]),
  ...tier('👑','Parlay King',parlays.length,'Win parlays', [3,10,25,50,100]),
  ...tier('🚀','Longshot Hunter',longshots.length,'Win +200 or longer wagers', [1,5,10,25,50]),
  ...tier('📚','Bookkeeper',settled.length,'Settle wagers', [10,50,100,250,500]),
  ...tier('📈','Volume Player',totalWagered,'Total dollars wagered', [500,2500,5000,10000,25000]),
  ...tier('💎','High Roller',biggestWin,'Single-wager profit dollars', [50,100,250,500,1000]),
  ...tier('🧠','Sharp Mind',wins.length,'Win wagers', [40,75,125,200,300]),
  {icon:'🛡️',title:'Iron Bank',desc:'Finish 50 settled wagers with positive net profit.',ok:settled.length>=50&&net>0},
  {icon:'🎰',title:'Lotto Ticket',desc:'Win a 10+ leg parlay.',ok:maxLegs>=10},
  {icon:'🏁',title:'Season Veteran',desc:'Settle 250 wagers.',ok:settled.length>=250},
  {icon:'🧙',title:'Fade the Crowd',desc:'Win a wager where simulated crowd sentiment is 75%+ against your side.',ok:longshots.length>=5&&wins.length>=25},
  {icon:'🧹',title:'Perfect Card',desc:'Finish a week with 10+ settled wagers and no losses.',ok:(()=>{const w=Number(document.getElementById('week')?.value||1);const wb=weeklyBetStats();return wb.bets.length>=10&&wb.losses.length===0})()},
  {icon:'🔥',title:'The Heater',desc:'Win 10 straight settled wagers.',ok:betStreaks().best>=10&&betStreaks().bestType==='W'},
  {icon:'🧊',title:'Ice Cold',desc:'Survive a 10-game winning season? No — avoid 10 straight losses.',ok:betStreaks().best>=10&&betStreaks().bestType==='L'},
  {icon:'💥',title:'Miracle Ticket',desc:'Win a +1000 or longer wager.',ok:wins.some(b=>Number(b.americanOdds)>=1000)},
  {icon:'🧭',title:'Full Slate',desc:'Settle a wager involving every game in a franchise week.',ok:false}
 ];}

function settledBetsForCurrent(){return franchiseLoaded?history.filter(b=>betBelongsToCurrentFranchise(b)&&['won','lost','void'].includes(b.status)):[]}
function betMarketType(b){if((b.legs||[]).length>1)return 'Parlays';return b.legs?.[0]?.kind?.startsWith('prop')?'Player Props':'Game Bets'}
function reputationFor(settledCount,wins){const n=Math.max(0,Number(settledCount)||0),w=Math.max(0,Number(wins)||0);if(n<10)return 'ROOKIE';const rate=n?w/n:0;if(n>=150&&rate>=.62)return 'LEGEND';if(n>=100&&rate>=.60)return 'ELITE';if(n>=60&&rate>=.57)return 'SHARP';if(n>=25&&rate>=.53)return 'SOLID';return 'ROOKIE'}

function currentProfile(){if(!activeWalletKey)return {name:'',avatar:'🏈',favoriteTeam:''};const w=wallets[activeWalletKey]||{};if(!w.profile||typeof w.profile!=='object')w.profile={name:'',avatar:'🏈',favoriteTeam:'',setupComplete:false};if(typeof w.profile.setupComplete!=='boolean')w.profile.setupComplete=!!String(w.profile.name||'').trim();return w.profile}
function profileCosmetics(){const shop=wallets[activeWalletKey]?.economy?.shop||{};const out=[];if(shop.highRoller)out.push({id:'highRoller',label:'💎 HIGH ROLLER',type:'title'});if(shop.sharpBadge)out.push({id:'sharpBadge',label:'🧠 SHARP MONEY',type:'badge'});if(shop.goldenBook)out.push({id:'goldenBook',label:'📚 GOLDEN BOOKKEEPER',type:'badge'});if(shop.greenSlip)out.push({id:'greenSlip',label:'🎟️ GREEN SLIP',type:'tag'});return out}
function profileDisplayName(){const p=currentProfile();return p.name||'PROFILE'}
function renderProfileMini(){const b=document.getElementById('profileBtn');if(!b)return;const p=currentProfile();const cosmetics=profileCosmetics();const title=cosmetics.find(x=>x.type==='title');b.textContent=`${p.avatar||'🏈'} ${profileDisplayName()}${title?' • '+title.label:''}`;b.title=cosmetics.length?cosmetics.map(x=>x.label).join(' • '):'Sportsbook Profile'}
function saveProfile(){if(!activeWalletKey){setStatus('Import a Franchise first.','err');return}const p=currentProfile();p.name=String(document.getElementById('profileName')?.value||'').trim().slice(0,28);p.avatar=String(document.getElementById('profileAvatar')?.value||'🏈').slice(0,4);p.favoriteTeam=String(document.getElementById('profileFavoriteTeam')?.value||'').trim().slice(0,32);p.setupComplete=true;wallets[activeWalletKey].profile=p;saveWallet();renderProfileMini();renderProfile();setStatus('Sportsbook profile saved to this Franchise.','ok')}
function profileStats(){const bets=history.filter(b=>betBelongsToCurrentFranchise(b));const settled=bets.filter(b=>['won','lost','void'].includes(b.status)||b.status==='won'&&b.settledAt);const wins=settled.filter(b=>b.status==='won');const losses=settled.filter(b=>b.status==='lost');const profit=settled.reduce((n,b)=>n+Number(b.profit||0),0);const wagered=settled.reduce((n,b)=>n+Number(b.wager||0),0);return {bets,settled,wins,losses,profit,wagered,roi:wagered?profit/wagered*100:0,rep:reputationFor(settled.length,wins.length)}}
function renderProfile(){const c=document.getElementById('profileContent');if(!c)return;if(!franchiseLoaded){c.innerHTML='<div class="empty">Import a Franchise first.</div>';return}const p=currentProfile(),st=profileStats(),ads=achievementData(),unlocked=ads.filter(a=>a.ok).slice(-8);const displayName=p.name||'PROFILE';const team=p.favoriteTeam||'No favorite team selected';const avatar=p.avatar||'🏈';c.innerHTML=`<div class="profile-grid"><article class="profile-card"><div class="profile-identity"><div class="profile-avatar">${escapeHtml(avatar)}</div><div><div class="profile-name">${escapeHtml(displayName)}</div><div class="profile-meta">${escapeHtml(team)} • ${escapeHtml(currentFranchiseLabel())}</div><div class="profile-meta">Reputation: <b style="color:var(--accent)">${st.rep}</b></div>${profileCosmetics().length?`<div class="profile-meta" style="color:var(--gold)">${profileCosmetics().map(x=>escapeHtml(x.label)).join(' • ')}</div>`:''}</div></div><div class="profile-stat-grid"><div class="profile-stat"><div class="note">RECORD</div><b>${st.wins.length}-${st.losses.length}</b></div><div class="profile-stat"><div class="note">NET PROFIT</div><b class="${st.profit>=0?'pos':'neg'}">${money(st.profit)}</b></div><div class="profile-stat"><div class="note">ROI</div><b>${st.roi.toFixed(1)}%</b></div></div><div class="profile-rec"><div><span>Settled wagers</span><b>${st.settled.length}</b></div><div><span>Current bankroll</span><b>${money(balance)}</b></div><div><span>Best streak</span><b>${betStreaks().best||0}</b></div><div><span>Biggest win</span><b>${money(st.wins.reduce((m,b)=>Math.max(m,Number(b.profit||0)),0))}</b></div></div></article><article class="profile-card"><div class="eyebrow">EDIT PROFILE</div><div class="profile-form"><label>Sportsbook Name<input id="profileName" maxlength="28" value="${escapeHtml(p.name||'') }" placeholder="e.g. Sharp Money"></label><label>Avatar<input id="profileAvatar" maxlength="4" value="${escapeHtml(avatar)}" placeholder="🏈"></label><label>Favorite Team<input id="profileFavoriteTeam" maxlength="32" value="${escapeHtml(p.favoriteTeam||'')}" placeholder="e.g. Ravens"></label><div class="note">These settings belong to this imported Franchise only. Switching to another save loads that save's own profile, bankroll, challenges, achievements, and betting history.</div><button class="btn primary" id="saveProfileBtn">Save Sportsbook Profile</button></div></article></div><article class="hero" style="margin-top:12px"><div class="eyebrow">CAREER BADGES</div><div class="note">Only achievements earned in this Franchise appear here. A brand-new Franchise starts with a clean badge record.</div><div class="profile-badges">${unlocked.length?unlocked.map(a=>`<span class="profile-badge">${escapeHtml(a.icon)} ${escapeHtml(a.title)}</span>`).join(''):'<span class="profile-badge locked">No achievement badges earned yet</span>'}${profileCosmetics().map(x=>`<span class="profile-badge" title="Purchased in Bankroll Shop">${escapeHtml(x.label)}</span>`).join('')}</div></article><article class="hero" style="margin-top:12px"><div class="eyebrow">WEEKLY RECAP</div><div class="note">Use Statistics for the full history. This profile keeps the career-level snapshot visible without creating another betting screen.</div><div class="profile-stat-grid"><div class="profile-stat"><div class="note">CURRENT WEEK</div><b>${Number(document.getElementById('week')?.value||1)}</b></div><div class="profile-stat"><div class="note">WEEK RECORD</div><b>${weeklyBetStats().wins.length}-${weeklyBetStats().losses.length}</b></div><div class="profile-stat"><div class="note">WEEK P/L</div><b class="${weeklyBetStats().profit>=0?'pos':'neg'}">${money(weeklyBetStats().profit)}</b></div></div></article>`;document.getElementById('saveProfileBtn')?.addEventListener('click',saveProfile)}
function openProfile(){if(!franchiseLoaded){setStatus('Import a Franchise first.','err');return}showPage('profile')}

function currentWeekGames(){const w=Number(document.getElementById('week')?.value||1),ph=window.selectedPhase||'regular';return (games||[]).filter(g=>String(g.phase||'regular')===String(ph)&&Number(g.phaseWeek??g.week+1)===w)}
function weeklyBetStats(){const w=Number(document.getElementById('week')?.value||1),ph=window.selectedPhase||'regular';const bets=settledBetsForCurrent().filter(b=>{const l=b.legs?.[0];return l&&String(l.phase||ph)===String(ph)&&Number(l.week??l.phaseWeek??0)===w});const wins=bets.filter(b=>b.status==='won');return {bets,wins,losses:bets.filter(b=>b.status==='lost'),profit:bets.reduce((n,b)=>n+Number(b.profit||0),0)}}
function betStreaks(){const arr=settledBetsForCurrent().slice().sort((a,b)=>new Date(a.settledAt||a.placedAt)-new Date(b.settledAt||b.placedAt));let cur=0,curType='',best=0,bestType='';for(const b of arr){const t=b.status==='won'?'W':b.status==='lost'?'L':'V';if(t==='V')continue;if(t===curType)cur++;else{curType=t;cur=1}if(cur>best){best=cur;bestType=t}}let current=0,currentType='';for(let i=arr.length-1;i>=0;i--){const t=arr[i].status==='won'?'W':arr[i].status==='lost'?'L':'V';if(t==='V')continue;if(!currentType)currentType=t;if(t!==currentType)break;current++}return {current,currentType,best,bestType}} 
function modelSnapshot(){const settled=settledBetsForCurrent();const wins=settled.filter(b=>b.status==='won').length;const base=settled.length?wins/settled.length:.55;const week=Number(document.getElementById('week')?.value||1);return [['M27 Core',base+.035],['Prop Model',Math.max(.45,base+.015)],['Sharp Model',Math.max(.45,base-.01)],['Market Pulse',Math.max(.45,base-.025)]].map((m,i)=>{const drift=(((week*3+i*5)%7)-3)/100;const rate=Math.max(.42,Math.min(.76,m[1]+drift));return {name:m[0],rate,last:Math.max(0,Math.min(10,Math.round(rate*10))),trend:rate>=.60?'HOT':rate<.53?'COLD':'STEADY'}})}
function renderIntelligenceLab(){
 const c=document.getElementById('intelligenceContent');if(!c)return;
 if(!franchiseLoaded){c.innerHTML='<div class="empty">Import a Madden 27 Franchise first to build your Intelligence Lab from real franchise data.</div>';return}
 const teamName=id=>{const t=teams.find(x=>String(x.id)===String(id));return t?.name||t?.displayName||String(id||'Unknown team')};
 const allGames=Array.isArray(games)?games:[], allTeams=Array.isArray(teams)?teams:[];
 const completed=allGames.filter(isPlayed), regularCompleted=completed.filter(g=>String(g.phase||'regular')==='regular');
 const scoreOf=g=>({away:Number(g.AwayScore)||0,home:Number(g.HomeScore)||0,total:(Number(g.AwayScore)||0)+(Number(g.HomeScore)||0),margin:Math.abs((Number(g.AwayScore)||0)-(Number(g.HomeScore)||0))});
 const scores=completed.map(g=>({g,...scoreOf(g)}));
 const avgPoints=scores.length?scores.reduce((n,x)=>n+x.total,0)/scores.length:0;
 const highest=scores.slice().sort((a,b)=>b.total-a.total)[0], closest=scores.filter(x=>x.margin>0).sort((a,b)=>a.margin-b.margin)[0];
 const regularTeams=allTeams.filter(t=>String(t.name||t.displayName||'').trim().toLowerCase()!=='practice');
 const baseRecords=new Map(regularTeams.map(t=>{const st=statsForTeam(t.id);return [String(t.id),{...st,pct:st.gp?(st.w+st.t*.5)/st.gp:0,diff:st.gp?(st.pf-st.pa)/st.gp:0}]}));
 const rankings=regularTeams.map(t=>{
   const st=statsForTeam(t.id), recent=regularCompleted.filter(g=>String(g.AwayTeam)===String(t.id)||String(g.HomeTeam)===String(t.id)).sort((a,b)=>Number(b.phaseWeek??b.SeasonWeek??b.week??0)-Number(a.phaseWeek??a.SeasonWeek??a.week??0)||Number(b.SeasonGameNum||0)-Number(a.SeasonGameNum||0)).slice(0,5);
   const form=recent.map(g=>{const sc=scoreOf(g), isAway=String(g.AwayTeam)===String(t.id);return (isAway?sc.away-sc.home:sc.home-sc.away)>0?'W':(isAway?sc.away-sc.home:sc.home-sc.away)<0?'L':'T'}).reverse();
   const pct=st.gp?(st.w+st.t*.5)/st.gp:0, diff=st.gp?(st.pf-st.pa)/st.gp:0;
   const opponents=regularCompleted.filter(g=>String(g.AwayTeam)===String(t.id)||String(g.HomeTeam)===String(t.id)).map(g=>String(g.AwayTeam)===String(t.id)?String(g.HomeTeam):String(g.AwayTeam));
   const oppPcts=opponents.map(id=>baseRecords.get(id)?.pct).filter(v=>Number.isFinite(v));
   const opponentPct=oppPcts.length?oppPcts.reduce((a,b)=>a+b,0)/oppPcts.length:null;
   const strengthAdj=opponentPct===null?0:(opponentPct-.5)*20;
   const diffScore=Math.max(-21,Math.min(21,diff*1.5));
   const rankScore=Math.max(0,Math.min(100,pct*60+30+diffScore+strengthAdj));
   return {...t,...st,pct,diff,form,opponentPct,strengthAdj,rankScore};
 }).filter(t=>t.gp>0).sort((a,b)=>b.rankScore-a.rankScore||b.pct-a.pct||b.diff-a.diff||b.pf-a.pf);
 const wk=Number(document.getElementById('week')?.value||1), phase=window.selectedPhase||'regular';
 const slate=allGames.filter(g=>String(g.phase||'regular')===phase&&Number(g.phaseWeek??g.week+1)===wk);
 const upcoming=slate.filter(g=>!isPlayed(g)).sort(gameSort), finished=slate.filter(isPlayed).sort(gameSort);
 const currentBets=history.filter(b=>betBelongsToCurrentFranchise(b));
 const settled=currentBets.filter(b=>['won','lost','void'].includes(b.status)&&((b.status!=='won')||!!b.settledAt));
 const graded=settled.filter(b=>b.status==='won'||b.status==='lost'), wins=graded.filter(b=>b.status==='won'), losses=graded.filter(b=>b.status==='lost'), voids=settled.filter(b=>b.status==='void');
 const wagered=graded.reduce((n,b)=>n+Math.max(0,Number(b.wager)||0),0);
 // Use recorded net profit when present. Exclude void tickets from ROI denominator and win-rate denominator.
 const profit=graded.reduce((n,b)=>n+Number(b.profit||0),0), winRate=graded.length?wins.length/graded.length*100:0, roi=wagered?profit/wagered*100:0;
 const card=(label,value,note='')=>`<article class="intel-metric"><div class="eyebrow">${label}</div><strong>${value}</strong><div class="note">${note}</div></article>`;
 const rankingRows=rankings.slice(0,10).map((t,i)=>`<tr><td class="intel-rank-muted">#${i+1}</td><td><b>${escapeHtml(t.name||t.displayName||t.id)}</b><div class="note">${t.w}-${t.l}${t.t?'-'+t.t:''} · ${t.gp} GP</div><div class="intel-form">${t.form.map(v=>`<span class="${v==='W'?'win':v==='L'?'loss':'tie'}">${v}</span>`).join('')||'<span class="intel-muted">No recent form</span>'}</div></td><td><b>${t.rankScore.toFixed(1)}</b>/100</td><td>${(t.pct*100).toFixed(1)}%</td><td class="${t.diff>=0?'pos':'neg'}">${t.diff>0?'+':''}${t.diff.toFixed(1)} / G</td><td>${t.opponentPct===null?'—':(t.opponentPct*100).toFixed(1)+'%'}</td><td>${t.pf-t.pa>0?'+':''}${t.pf-t.pa}</td></tr>`).join('');
 const intelTeam=(g,side)=>{const id=side==='away'?g.AwayTeam:g.HomeTeam,name=side==='away'?(g.awayName||teamName(g.AwayTeam)):(g.homeName||teamName(g.HomeTeam));const played=regularCompleted.filter(x=>String(x.AwayTeam)===String(id)||String(x.HomeTeam)===String(id)).sort((a,b)=>Number(b.phaseWeek??b.SeasonWeek??b.week??0)-Number(a.phaseWeek??a.SeasonWeek??a.week??0)||Number(b.SeasonGameNum||0)-Number(a.SeasonGameNum||0));const recent=played.slice(0,3);let pf=0,pa=0;for(const x of played){const away=String(x.AwayTeam)===String(id);pf+=Number(away?x.AwayScore:x.HomeScore)||0;pa+=Number(away?x.HomeScore:x.AwayScore)||0}const form=recent.map(x=>{const away=String(x.AwayTeam)===String(id),d=(Number(away?x.AwayScore:x.HomeScore)||0)-(Number(away?x.HomeScore:x.AwayScore)||0);return d>0?'W':d<0?'L':'T'});const st=statsForTeam(id);const props=(currentData?.playerProps||[]).filter(x=>String(x.teamName||x.team||'').toLowerCase()===String(name).toLowerCase()&&x.average!==undefined&&Number.isFinite(Number(x.average))).sort((a,b)=>Number(b.average)-Number(a.average)).slice(0,2);return {name,gp:played.length,avgFor:played.length?pf/played.length:null,avgAgainst:played.length?pa/played.length:null,form:form.join(' · ')||'No games',record:st?.gp?`${st.w}-${st.l}${st.t?'-'+st.t:''}`:'0 GP',leaders:props.map(x=>`${x.name||'Player'} · ${x.label||x.stat} ${Number(x.average).toFixed(1)} avg`)}};
 const matchupCards=upcoming.slice(0,8).map(g=>{const line=modelLine(g),away=intelTeam(g,'away'),home=intelTeam(g,'home');const panel=t=>`<div class="intel-team-snapshot"><div class="intel-team-heading"><b>${escapeHtml(t.name)}</b><span>${escapeHtml(t.record)}</span></div><div class="intel-team-stats"><div><span>PF / game</span><b>${t.avgFor===null?'—':t.avgFor.toFixed(1)}</b></div><div><span>PA / game</span><b>${t.avgAgainst===null?'—':t.avgAgainst.toFixed(1)}</b></div><div><span>Last 3</span><b>${escapeHtml(t.form)}</b></div></div>${t.leaders.length?`<div class="intel-leaders"><span>Available player averages</span>${t.leaders.map(x=>`<div>${escapeHtml(x)}</div>`).join('')}</div>`:''}</div>`;const limited=Math.min(away.gp,home.gp)<3;let insight='No clear statistical edge yet; compare more completed games as the season develops.';if(away.avgFor!==null&&home.avgFor!==null&&away.avgAgainst!==null&&home.avgAgainst!==null){const off=away.avgFor-home.avgFor,def=away.avgAgainst-home.avgAgainst;if(Math.abs(off)>=3)insight=`${off>0?away.name:home.name} has the scoring edge: ${(Math.abs(off)).toFixed(1)} more points per game.`;else insight='Scoring averages are close between these teams.';if(Math.abs(def)>=3)insight+=` ${def<0?away.name:home.name} allows ${Math.abs(def).toFixed(1)} fewer points per game.`;}return `<article class="intel-match intel-match-expanded"><div class="eyebrow">${escapeHtml(g.DayOfWeek||'UPCOMING')} · ${escapeHtml(formatGameTime(g))}</div><h4>${escapeHtml(away.name)} @ ${escapeHtml(home.name)}</h4><div class="intel-model-line"><span>MODEL CONTEXT</span><b>${escapeHtml(away.name)} ${Number(line.spread)>0?'+':''}${Number(line.spread).toFixed(1)}</b><b>TOTAL ${Number(line.total).toFixed(1)}</b></div><div class="intel-team-comparison">${panel(away)}${panel(home)}</div><div class="intel-edge-panel"><div class="eyebrow">WHAT THE NUMBERS SAY</div><p>${escapeHtml(insight)}</p><small>Recent form: ${escapeHtml(away.name)} ${escapeHtml(away.form)} · ${escapeHtml(home.name)} ${escapeHtml(home.form)}</small></div>${limited?'<div class="intel-sample-warning">Limited sample: one or both teams have fewer than three completed regular-season games.</div>':''}<p class="intel-disclaimer">Team scoring averages use completed regular-season games. Player averages appear only when supplied by imported franchise prop data. Model lines are directional context, not calibrated win probabilities.</p></article>`}).join('');
 const resultCards=finished.slice().reverse().slice(0,6).map(g=>{const sc=scoreOf(g),winner=sc.away===sc.home?'The game finished tied':sc.away>sc.home?(g.awayName||teamName(g.AwayTeam)):(g.homeName||teamName(g.HomeTeam)),loser=sc.away===sc.home?'':sc.away>sc.home?(g.homeName||teamName(g.HomeTeam)):(g.awayName||teamName(g.AwayTeam));let remark=sc.margin===0?'Neither side separated on the scoreboard.':sc.margin<=3?`${winner} escaped with a one-score finish; ${loser} stayed within one possession.`:sc.margin>=21?`${winner} delivered a convincing result, winning by ${sc.margin}.`:`${winner} finished ahead by ${sc.margin}.`;if(sc.total>=60)remark+=` The game produced ${sc.total} combined points, a high-scoring result.`;return `<article class="intel-result"><span class="eyebrow">WEEK ${wk} · FINAL</span><h4>${escapeHtml(g.awayName||teamName(g.AwayTeam))} ${sc.away} — ${sc.home} ${escapeHtml(g.homeName||teamName(g.HomeTeam))}</h4><p>${escapeHtml(remark)}</p></article>`}).join('');
 const nextGames=allGames.filter(g=>!isPlayed(g)&&String(g.phase||'regular')===phase&&Number(g.phaseWeek??g.week+1)>wk).sort((a,b)=>Number(a.phaseWeek??a.week+1)-Number(b.phaseWeek??b.week+1)||gameSort(a,b));const nextWeek=nextGames.length?Number(nextGames[0].phaseWeek??nextGames[0].week+1):null;const nextSlate=nextWeek===null?[]:nextGames.filter(g=>Number(g.phaseWeek??g.week+1)===nextWeek);
 const regularTotal=regularCompleted.reduce((n,g)=>n+scoreOf(g).total,0), teamGames=regularCompleted.length*2;
 c.innerHTML=`<div class="intel-metrics">${card('COMPLETED GAMES',completed.length,`${allGames.length} games loaded across franchise phases`)}${card('AVG. COMBINED POINTS',scores.length?avgPoints.toFixed(1):'—','Completed games only; both teams combined')}${card(`WEEK ${wk} SLATE`,`${upcoming.length} upcoming`,`${finished.length} completed in selected week`)}${card('BET WIN RATE',graded.length?winRate.toFixed(1)+'%':'—',`${wins.length} wins · ${losses.length} losses · ${voids.length} voids excluded`)}${card('BET ROI',wagered?(roi>0?'+':'')+roi.toFixed(1)+'%':'—',`${money(profit)} net on ${money(wagered)} graded stake`)}</div>
 <section class="intel-panel"><div class="eyebrow">FRANCHISE PULSE</div><h3>League at a glance</h3><div class="intel-facts"><div class="intel-fact"><span>Regular-season games completed</span><strong>${regularCompleted.length}</strong></div><div class="intel-fact"><span>Unplayed games remaining</span><strong>${allGames.filter(g=>!isPlayed(g)).length}</strong></div><div class="intel-fact"><span>Average points per team per game</span><strong>${teamGames?(regularTotal/teamGames).toFixed(1)+' PPG':'—'}</strong></div><div class="intel-fact"><span>Highest-scoring game</span><strong>${highest?`${highest.total} points`:'Not available'}</strong></div><div class="intel-fact"><span>Closest completed game</span><strong>${closest?`${closest.margin}-point margin`:'No non-tied results'}</strong></div><div class="intel-fact"><span>Teams with completed games</span><strong>${rankings.length} / ${allTeams.filter(t=>String(t.name||t.displayName||'').trim().toLowerCase()!=='practice').length}</strong></div></div>${highest?`<p class="intel-disclaimer">Highest-scoring game: ${escapeHtml(highest.g.awayName||teamName(highest.g.AwayTeam))} ${highest.away} — ${highest.home} ${escapeHtml(highest.g.homeName||teamName(highest.g.HomeTeam))}. The league average uses regular-season games only.</p>`:'<p class="intel-disclaimer">League scoring averages appear after completed regular-season games are available.</p>'}</section>
 <section class="intel-panel"><div class="eyebrow">RESULTS DESK · WEEK ${wk}</div><h3>Latest results</h3><div class="intel-results">${resultCards||'<div class="empty">No completed games in the selected week yet. Final scores and commentary appear here after the franchise records completed games.</div>'}</div><div class="intel-panel" style="margin-top:12px;background:#0b1016"><div class="eyebrow">NEXT SLATE</div><h3>${nextWeek===null?'Awaiting next slate':`${escapeHtml(phaseLabel(phase))} · Week ${nextWeek}`}</h3><p class="intel-description">${nextSlate.length?nextSlate.slice(0,8).map(g=>`${escapeHtml(g.awayName||teamName(g.AwayTeam))} at ${escapeHtml(g.homeName||teamName(g.HomeTeam))}`).join(' · '):'No later unplayed slate is available in this phase yet.'}</p></div></section>
 <section class="intel-panel"><div class="eyebrow">POWER RANKINGS</div><h3>Teams ranked by results, point differential and opponent strength</h3><p class="intel-description">Rating out of 100 combines win percentage, point differential per game and average opponents’ win percentage. Opponent strength is descriptive; small samples can move rankings sharply.</p><div class="intel-table-wrap"><table class="intel-table"><thead><tr><th>Rank</th><th>Team / Recent form</th><th>Rating</th><th>Win %</th><th>Diff / game</th><th>Opp. win %</th><th>Total diff</th></tr></thead><tbody>${rankingRows||'<tr><td colspan="7">No completed regular-season results available for ranking.</td></tr>'}</tbody></table></div><p class="intel-disclaimer">Early-season records can change sharply. Rating uses win percentage (60 points), capped point differential (±21 points around a 30-point baseline), and opponent strength (±10 points around a .500 opponent baseline). It is not Madden’s internal team rating or a calibrated prediction.</p></section>
 <section class="intel-panel"><div class="eyebrow">MATCHUP INTELLIGENCE · ${escapeHtml(phaseLabel(phase).toUpperCase())} WEEK ${wk}</div><h3>Upcoming matchup context</h3><div class="intel-match-grid">${matchupCards||'<div class="empty">No upcoming games in this selected slate. Change the phase or week to inspect another slate.</div>'}</div><p class="intel-disclaimer">Model lines are directional context derived from available franchise results, not calibrated win probabilities. Matchup records and point differentials are based on completed regular-season games.</p></section>`;
}

function renderCommandCenter(){const c=document.getElementById('commandContent');if(!c)return;if(!franchiseLoaded){c.innerHTML='<div class="empty">Import a franchise first.</div>';return}const wk=Number(document.getElementById('week')?.value||1),stats=weeklyBetStats(),settled=settledBetsForCurrent(),profit=settled.reduce((n,b)=>n+Number(b.profit||0),0),streak=betStreaks(),models=modelSnapshot();const markets=currentData?.playerProps||[];const top=markets.slice().sort((a,b)=>Math.abs(Number(b.line)-Number(b.average||b.line))-Math.abs(Number(a.line)-Number(a.average||a.line))).slice(0,1)[0];const gap=top?Math.abs(Number(top.line)-Number(top.average||top.line)):0;const bestMarket=top?`${top.name||'Player'} ${top.label||top.stat} ${Number(top.line).toFixed(1)}`:'No player market available';const gamesNow=currentWeekGames();c.innerHTML=`<div class="command-grid"><article class="command-card"><div class="eyebrow">BANKROLL</div><b>${money(balance)}</b><div class="note">Current available bankroll</div></article><article class="command-card"><div class="eyebrow">WEEK ${wk} PROFIT</div><b class="${stats.profit>=0?'pos':'neg'}">${money(stats.profit)}</b><div class="note">${stats.wins.length}-${stats.losses.length} settled wagers</div></article><article class="command-card"><div class="eyebrow">CURRENT STREAK</div><b>${streak.current||0}${streak.currentType==='W'?' WINS':streak.currentType==='L'?' LOSSES':''}</b><div class="note">Best: ${streak.best||0} ${streak.bestType==='W'?'wins':streak.bestType==='L'?'losses':'-'}</div></article></div><div class="command-grid"><article class="hero"><div class="eyebrow">🔥 HOTTEST MARKET</div><h3>${escapeHtml(bestMarket)}</h3><div class="note">${gap?`${gap.toFixed(1)} units of separation from the sample average.`:'Awaiting enough sample data.'}</div></article><article class="hero"><div class="eyebrow">🤖 MODEL LEADER</div><h3>${models.slice().sort((a,b)=>b.rate-a.rate)[0].name}</h3><div class="note">${(models.slice().sort((a,b)=>b.rate-a.rate)[0].rate*100).toFixed(1)}% simulated current form</div></article><article class="hero"><div class="eyebrow">🏈 WEEK SNAPSHOT</div><h3>${gamesNow.length} games</h3><div class="note">${gamesNow.filter(isPlayed).length} completed • ${gamesNow.filter(g=>!isPlayed(g)).length} upcoming</div></article></div><article class="hero" style="margin-top:12px"><div class="eyebrow">WEEK ${wk} SNAPSHOT</div><div class="command-list">${gamesNow.slice(0,8).map(g=>`<div><span>${escapeHtml(g.awayName)} @ ${escapeHtml(g.homeName)}</span><b>${isPlayed(g)?`${Number(g.AwayScore)||0}-${Number(g.HomeScore)||0}`:'UPCOMING'}</b></div>`).join('')||'<div class="note">No games available.</div>'}</div></article><div class="command-grid" style="margin-top:12px"><article class="hero"><div class="eyebrow">📈 MARKET MOVERS</div><div class="command-list">${markets.slice().sort((a,b)=>Math.abs(Number(b.line)-Number(b.average||b.line))-Math.abs(Number(a.line)-Number(a.average||a.line))).slice(0,5).map(m=>{const gap=Number(m.line)-Number(m.average||m.line);return `<div><span>${escapeHtml(m.name||'Player')} • ${escapeHtml(m.label||m.stat)}</span><b>${gap>=0?'+':''}${gap.toFixed(1)}</b></div>`}).join('')||'<div class="note">No market movement context yet.</div>'}</div></article><article class="hero"><div class="eyebrow">WHY THESE LINES?</div><div class="note" style="line-height:1.6">Lines are generated from Franchise data. Compare the current line against season averages and recent results before betting. Player Prop Research now surfaces the same context at the individual market level.</div></article></div>`}
function renderProps(){
  const c=document.getElementById('propsContent');
  if(!franchiseLoaded){c.innerHTML='<div class="empty">Import a Franchise first.</div>';return}
  const props=currentData?.playerProps||[];let upcoming=currentGameSet().filter(g=>!isPlayed(g));
  if(!upcoming.length) upcoming=socialUpcomingGames().slice(0,16);
  const propSource=currentData?.summary?.playerPropSource||'historical';const groups=[];
  for(const g of upcoming){
    const byPlayer=new Map();
    for(const p of props){
      const playerTeamIndex=(p.teamIndex!==null&&p.teamIndex!==undefined)?String(p.teamIndex):null;
      const awayTeamIndex=(g.awayTeamResolved?.TeamIndex!==null&&g.awayTeamResolved?.TeamIndex!==undefined)?String(g.awayTeamResolved.TeamIndex):null;
      const homeTeamIndex=(g.homeTeamResolved?.TeamIndex!==null&&g.homeTeamResolved?.TeamIndex!==undefined)?String(g.homeTeamResolved.TeamIndex):null;
      const side=(playerTeamIndex!==null&&awayTeamIndex!==null&&playerTeamIndex===awayTeamIndex)?'AWAY':(playerTeamIndex!==null&&homeTeamIndex!==null&&playerTeamIndex===homeTeamIndex)?'HOME':(p.teamName&&p.teamName===g.awayName?'AWAY':p.teamName&&p.teamName===g.homeName?'HOME':null);
      if(!side)continue;
      const key=String(p.playerId);const entry=byPlayer.get(key)||{playerId:p.playerId,name:p.name,position:p.position,team:p.teamName||side,side,depthRank:p.depthRank??null,depthPosition:p.depthPosition||p.position,markets:[]};if(entry.depthRank==null&&p.depthRank!=null)entry.depthRank=p.depthRank;if(!entry.depthPosition&&p.depthPosition)entry.depthPosition=p.depthPosition;entry.markets.push(p);byPlayer.set(key,entry)
    }
    const players=assignPropDepth([...byPlayer.values()]);if(players.length)groups.push({g,players})
  }
  if(!groups.length){const d=currentData?.summary?.statMappings?._diagnostic||{};c.innerHTML=`<div class="empty"><b>No player props are available for the selected week.</b><br><br>This franchise did not produce usable player markets for the current matchups.<br><small>Player-stat rows: ${currentData?.summary?.playerGameStatRows??0} • Completed games: ${currentData?.summary?.completedGameCount??0} • Stat links: ${d.ownerLinks??0}</small></div>`;return}
  const marketOrder={passYds:1,passTD:2,completions:3,rushYds:4,rushAtt:5,recYds:6,receptions:7};groups.sort((a,b)=>gameSort(a.g,b.g));
  c.innerHTML=`${propSource==='rosterProjection'?'<div class="status ok" style="margin-bottom:12px">Projection mode: this imported franchise has no usable historical player-stat sample yet, so props are calculated from the loaded franchise roster/ratings. No bundled save is used.</div>':propSource==='mixedProjection'?'<div class="status ok" style="margin-bottom:12px">Markets combine available franchise game samples with roster-based projections for players who have not appeared in a completed game yet.</div>':''}<div class="prop-games">${groups.map((group,i)=>{
    const g=group.g;const title=`Week ${Number(g.phaseWeek||g.week+1)} • ${g.awayName} @ ${g.homeName}`;const totalMarkets=group.players.reduce((n,p)=>n+p.markets.length,0);
    const byDepth=new Map();for(const p of group.players){const k=propPositionKey(p.position);const arr=byDepth.get(k)||[];arr.push(p);byDepth.set(k,arr)}
    const sections=[...byDepth.entries()].filter(([k])=>k!=='OTHER').sort((a,b)=>['QB','RB','WR','TE'].indexOf(a[0])-['QB','RB','WR','TE'].indexOf(b[0]));
    return `<details class="prop-game" ${i===0?'open':''}><summary><div style="display:flex;align-items:center;gap:10px"><div class="prop-game-teamlogos">${teamLogoForName(g.awayName,true)}${teamLogoForName(g.homeName,true)}</div><div><div class="prop-game-title">${title}</div><div class="prop-game-meta">${g.phaseLabel||'Regular Season'} • ${String(g.DayOfWeek||'').toUpperCase()} ${formatGameTime(g)} • ${group.players.length} players with ${totalMarkets} markets</div></div></div><span class="prop-game-count">VIEW PROPS ▾</span></summary><div class="prop-players">${sections.map(([position,players])=>`<section class="prop-depth-section"><div class="prop-depth-title">${propSectionLabel(position)}</div>${players.sort((a,b)=>{const ar=Number(a.depthRank),br=Number(b.depthRank),av=Number.isInteger(ar)&&ar>0,bv=Number.isInteger(br)&&br>0;if(av!==bv)return av?-1:1;if(av&&bv&&ar!==br)return ar-br;return String(a.name||'').localeCompare(String(b.name||''))}).map(p=>{const markets=[...p.markets].sort((a,b)=>(marketOrder[a.stat]||99)-(marketOrder[b.stat]||99));return `<article class="prop-player-card prop-depth-player"><div class="prop-player-head"><div style="display:flex;align-items:center;gap:9px;min-width:0">${teamLogoForName(p.team,true)}<div><div class="prop-player-name">${p.name}<span class="prop-role">${p.role}</span></div><div class="prop-player-info">${p.team} • ${p.roleText} • ${p.markets[0]?.games||0} game sample</div><div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:5px">${playerProfileButton(p.playerId)}</div></div></div><span class="tag">${p.side}</span></div><div class="prop-market-grid">${markets.map(m=>{const overOdds=propOdds(m,'over'),underOdds=propOdds(m,'under');return `<div class="prop-market-box"><div class="prop-market-top"><div class="prop-market-label">${m.label} • Avg ${m.average}</div><button class="research-btn" data-prop-research='${socialPayload({playerId:m.playerId,stat:m.stat,gameIndex:g.index})}'>RESEARCH</button></div><div class="prop-market-buttons"><button data-prop="${encodeURIComponent(JSON.stringify({label:`${m.name} O ${m.line} ${m.label}`,market:m.label,display:`O ${m.line} ${fmtOdds(overOdds)}`,odds:overOdds,gameId:gameKey(g),gameIndex:g.index,week:g.week,phaseWeek:g.phaseWeek,phase:g.phase,away:g.awayName,home:g.homeName,kind:'propOver',line:m.line,playerId:m.playerId,propStat:m.stat}))}"><span>OVER</span><b>O ${m.line} <small>${fmtOdds(overOdds)}</small></b></button><button data-prop="${encodeURIComponent(JSON.stringify({label:`${m.name} U ${m.line} ${m.label}`,market:m.label,display:`U ${m.line} ${fmtOdds(underOdds)}`,odds:underOdds,gameId:gameKey(g),gameIndex:g.index,week:g.week,phaseWeek:g.phaseWeek,phase:g.phase,away:g.awayName,home:g.homeName,kind:'propUnder',line:m.line,playerId:m.playerId,propStat:m.stat}))}"><span>UNDER</span><b>U ${m.line} <small>${fmtOdds(underOdds)}</small></b></button></div></div>`}).join('')}</div></article>`}).join('')}</section>`).join('')}</div></details>`
  }).join('')}</div>`;
  c.querySelectorAll('[data-prop]').forEach(b=>b.addEventListener('click',()=>{const x=JSON.parse(decodeURIComponent(b.dataset.prop));slip.push({...x,key:crypto.randomUUID()});saveState();renderSlip();setStatus('Player prop added to bet slip.','ok')}));c.querySelectorAll('[data-prop-research]').forEach(b=>b.addEventListener('click',()=>{const x=JSON.parse(decodeURIComponent(b.dataset.propResearch));openPropResearch(x.playerId,x.stat,x.gameIndex)}))
}
