function toggleNavGroup(key){const g=document.querySelector(`[data-nav-group="${key}"]`);if(!g)return;setNavGroup(key,g.classList.contains('collapsed'));saveNavGroups()}
function showPage(p){activePage=p;const group=NAV_PAGE_GROUP[p];if(group)setNavGroup(group,true);document.querySelectorAll('.nav button[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===p));document.querySelectorAll('.page').forEach(x=>x.classList.remove('active'));document.getElementById(p+'Page').classList.add('active');if(p==='games')renderGames();if(p==='command')renderCommandCenter();if(p==='intelligence')renderIntelligenceLab();if(p==='standings')renderStandings();if(p==='active')renderActiveBets();if(p==='history')renderHistory();if(p==='stats')renderStats();if(p==='props')renderProps();if(p==='economy')renderEconomy();if(p==='challenges')renderChallenges();if(p==='profile')renderProfile();if(['forum','aiPicks','suggested','trending','insights','leaderboard'].includes(p))renderSocialPage(p)}
function phaseLabel(phase){return phase==='preseason'?'Preseason':phase==='playoffs'?'Playoffs':phase==='superbowl'?'Super Bowl':'Regular Season'}
