 const gamesOut=(games||[]).slice().map(g=>{const l=modelLine(g);return {index:g.index,gameId:gameKey(g),week:g.week,phase:g.phase||'regular',phaseLabel:g.phaseLabel||'Regular Season',phaseWeek:g.phaseWeek,awayName:g.awayName,homeName:g.homeName,played:isPlayed(g),awayScore:g.AwayScore,homeScore:g.HomeScore,awayML:l.awayML,homeML:l.homeML,spread:l.spread,awaySpread:l.awaySpread,homeSpread:l.homeSpread,total:l.total,over:l.over,under:l.under};});
